-- Deterministic RFC 4122 v4-shaped identifier (the API validates UUIDs strictly).
create or replace function public.pro_quote_circuit_uuid(p_seed text) returns uuid
language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(m,1,12)||'4'||substr(m,14,3)||'8'||substr(m,18,15))::uuid from (select md5(p_seed) m) x $$;

create or replace function public.pro_contract_starter_create(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_contract_actions;starter jsonb;lang text;key text;tid uuid;t public.pro_contract_templates;clauses jsonb;e jsonb;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'starter_create' then raise exception 'Invalid contract action' using errcode='22023';end if;
 perform public.pro_contract_expect(p_input,array['action','actionId','workId','id','starter','language','estimateId']);
 aid:=public.pro_contract_uuid(p_input->'actionId');
 if jsonb_typeof(p_input->'starter') is distinct from 'string' or jsonb_typeof(p_input->'language') is distinct from 'string' or p_input->>'language' not in('es','en') then raise exception 'Invalid starter' using errcode='22023';end if;
 key:=p_input->>'starter';lang:=p_input->>'language';starter:=public.pro_contract_starters()->key->lang;
 if starter is null then raise exception 'Invalid starter' using errcode='22023';end if;
 -- Same lock order and receipt table as pro_contracts_mutate.
 perform pg_advisory_xact_lock(hashtextextended('pro-contract-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_contract_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-contracts:'||p_actor::text,0));
 tid:=public.pro_quote_circuit_uuid('pro-contract-starter:'||p_actor::text||':'||key||':'||lang);
 select * into t from public.pro_contract_templates where owner_id=p_actor and id=tid for update;
 if found and t.archived then raise exception 'Restore the starter template first' using errcode='22023',hint='pro_contract_starter_archived';end if;
 if not found then
  if (select count(*) from public.pro_contract_templates where owner_id=p_actor)>=200 then raise exception 'Too many templates' using errcode='22023';end if;
  clauses:='[]'::jsonb;
  for e in select value from jsonb_array_elements(starter->'clauses') loop clauses:=clauses||public.pro_contract_clause_item(gen_random_uuid(),e->>'title',e->>'body',null);end loop;
  insert into public.pro_contract_templates(owner_id,id,title,description,deposit_percent,clauses) values(p_actor,tid,starter->>'title',starter->>'description',(starter->>'depositPercent')::numeric,clauses) returning * into t;
  perform public.pro_contract_history_add(p_actor,p_actor,public.pro_quote_circuit_uuid('pro-contract-starter-install:'||aid::text),'template',t.id,null,'starter_install',null,public.pro_contract_template_json(t,true));
 end if;
 result:=public.pro_contract_apply(p_actor,jsonb_build_object('action','contract_create','actionId',aid,'workId',p_input->'workId','id',p_input->'id','templateId',tid,'title',null,'language',lang,'estimateId',p_input->'estimateId','depositPercent',null),aid);
 insert into public.pro_contract_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- 3. customer: quotes shared for this job
drop function if exists public.pro_private_estimate_publication_project_client(uuid,uuid);
create or replace function public.pro_client_project_quotes_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;w public.pro_work;items jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and status in('confirmed','completed') and work_id is not null;
 if not found then return jsonb_build_object('items','[]'::jsonb);end if;
 select * into w from public.pro_work where user_id=r.owner_id and id=r.work_id;
 if not found then return jsonb_build_object('items','[]'::jsonb);end if;
 select coalesce(jsonb_agg(jsonb_build_object('publicationId',x.id,'title',x.title,'version',x.version,'status',x.status,'totalCents',x.total,'currency',x.currency,'sharedAt',x.created_at) order by x.created_at desc,x.id),'[]'::jsonb) into items from (
  select distinct on(v.estimate_id) v.id,v.content->>'title' title,v.version,s.status,(v.content->>'totalCents')::bigint total,v.content->>'currency' currency,v.created_at
  from public.pro_private_estimate_publications v join public.pro_private_estimate_publication_states s on s.publication_id=v.id
  where v.owner_id=r.owner_id and s.recipient_id=p_actor and s.status in('shared','changes_requested','accepted','declined')
   and(exists(select 1 from public.pro_project_estimate_rows(r.owner_id,w) e where e.estimate_id=v.estimate_id and e.relation='project')
    or exists(select 1 from public.pro_private_estimate_publication_recipients b where b.owner_id=v.owner_id and b.estimate_id=v.estimate_id and b.proof->>'kind'='linked' and b.proof->>'requestId'=r.id::text))
  order by v.estimate_id,v.version desc limit 50) x;
 return jsonb_build_object('items',items);
end $$;

do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
  and p.proname in('pro_quote_circuit_uuid','pro_quote_circuit_target_work','pro_quote_circuit_auto_continue','pro_quote_circuit_on_accept','pro_contract_starters','pro_contract_starter_create','pro_client_project_quotes_read') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_quote_circuit_on_accept(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== pro-reports-local.sql =====
-- Round 7B (Houzz parity: Reports): financial and jobs reports for the owner, read-only.
-- One reader, security invoker, service_role only (the /api/pro/reports route passes the
-- authenticated actor). Every figure comes from the existing single formulas:
--   * per job: pro_work_overview_read(...,'finance') (agreed, paid, invoiced, costs, result),
--   * invoiced: non-archived invoice drafts; collected: payments received (pro_invoice_payments);
--   * outstanding/aging: per invoice draft, total minus non-voided payment applications, aged by
--     its creation day in America/Costa_Rica (0-30, 31-60, 61-90, 90+ days).
-- CRC cents everywhere (bigint). Nothing is written.
create or replace function public.pro_reports_read(p_actor uuid,p_from date default null,p_to date default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;jobs jsonb;aging jsonb;invoiced bigint;collected bigint;outstanding bigint;w record;fin jsonb;
begin
 if p_actor is null then raise exception 'Invalid actor' using errcode='22023';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if (p_from is not null and p_from not between date'2000-01-01' and date'2100-12-31') or (p_to is not null and p_to not between date'2000-01-01' and date'2100-12-31') or (p_from is not null and p_to is not null and p_from>p_to) then raise exception 'Invalid report period' using errcode='22023';end if;
 -- Invoices in the period (by creation day, Costa Rica), not archived.
 with d as (
  select d.id,d.total_cents,(d.created_at at time zone 'America/Costa_Rica')::date as day,
   d.total_cents-coalesce((select sum(a.amount_cents) from public.pro_invoice_payment_applications a where a.user_id=d.user_id and a.draft_id=d.id and not exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)),0) as open_cents
  from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=p_actor and not coalesce(m.archived,false)
   and (p_from is null or (d.created_at at time zone 'America/Costa_Rica')::date>=p_from) and (p_to is null or (d.created_at at time zone 'America/Costa_Rica')::date<=p_to))
 select coalesce(sum(total_cents),0)::bigint,coalesce(sum(greatest(open_cents,0)),0)::bigint,
  jsonb_build_object(
   'd0_30',coalesce(sum(greatest(open_cents,0)) filter(where today-day<=30),0)::bigint,
   'd31_60',coalesce(sum(greatest(open_cents,0)) filter(where today-day between 31 and 60),0)::bigint,
   'd61_90',coalesce(sum(greatest(open_cents,0)) filter(where today-day between 61 and 90),0)::bigint,
   'd90_plus',coalesce(sum(greatest(open_cents,0)) filter(where today-day>90),0)::bigint,
   'openInvoices',count(*) filter(where open_cents>0))
 into invoiced,outstanding,aging from d;
 select coalesce(sum(p.amount_cents),0)::bigint into collected from public.pro_invoice_payments p
  where p.user_id=p_actor and (p_from is null or p.received_on>=p_from) and (p_to is null or p.received_on<=p_to);
 jobs:='[]'::jsonb;
 for w in select x.id,x.service,x.client,x.stage,coalesce(x.cancelled,false) cancelled,x.start,x."end" from public.pro_work x where x.user_id=p_actor order by coalesce(x.start,'') desc,x.id limit 200 loop
  fin:=public.pro_work_overview_read(p_actor,w.id,'finance');
  if fin is null then continue;end if;
  jobs:=jobs||jsonb_build_array(jsonb_build_object('workId',w.id,'service',coalesce(w.service,''),'client',coalesce(w.client,''),'stage',coalesce(w.stage,''),'cancelled',w.cancelled,
   'start',nullif(left(coalesce(w.start,''),10),''),'end',nullif(left(coalesce(w."end",''),10),''),
   'agreedCents',fin->'agreedCents','agreedNetCents',fin->'agreedNetCents','invoicedCents',coalesce((fin->>'invoicedCents')::bigint,0),'paidCents',coalesce((fin->>'paidCents')::bigint,0),'balanceCents',fin->'balanceCents',
   'costCents',coalesce((fin->>'costCents')::bigint,0),'committedCents',coalesce((fin->>'committedCents')::bigint,0),'resultCents',fin->'resultCents'));
   -- balance/agreed/result stay null while the job has no agreement («Sin definir»).
 end loop;
 return jsonb_build_object('today',today,'from',p_from,'to',p_to,'invoicedCents',invoiced,'collectedCents',collected,'outstandingCents',outstanding,'aging',aging,'jobs',jobs,'truncated',(select count(*) from public.pro_work where user_id=p_actor)>200);
end $$;
revoke all on function public.pro_reports_read(uuid,date,date) from public,anon,authenticated;
grant execute on function public.pro_reports_read(uuid,date,date) to service_role;

-- ===== work-change-details-local.sql =====
-- LOCAL PRO ONLY. Round 7B (Houzz parity: change orders). Adds to the existing change flow
-- (pro_work_changes_mutate, unchanged signatures and rules):
--  * per line, optional quantity (qtyMilli), unit cost (unitCostCents) and markup (markupBps); when
--    all three are given the line amount must be exactly round(qty × cost × (1 + markup)), so the
--    customer total still comes only from amountCents (same agreement formula, no double counting);
--  * per change, optional schedule impact in days (scheduleDays 0..365) carried in the propose input;
--  * when the change is accepted (customer, or the owner recording an external approval), the plan
--    of the job moves: the tasks that end last get their planned end pushed by those days, once,
--    and the schedule revision is bumped (CAS readers reload). Immutable: the days and the shift are
--    recorded on the change row and never re-applied.
-- Triggers run inside the mutate transaction: any invalid detail raises 22023 and nothing is kept.
begin;
alter table public.pro_work_changes add column if not exists schedule_days integer not null default 0;
alter table public.pro_work_changes add column if not exists schedule_applied_at timestamptz;
alter table public.pro_work_changes add column if not exists schedule_shifted_tasks integer not null default 0;
do $$begin
 if not exists(select 1 from pg_constraint where conname='pro_work_changes_schedule_days_check') then
  alter table public.pro_work_changes add constraint pro_work_changes_schedule_days_check check(schedule_days between 0 and 365);
 end if;
end$$;

create or replace function public.pro_work_change_lines_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare line jsonb;keys text[];q numeric;cost numeric;markup numeric;expected numeric;
begin
 for line in select value from jsonb_array_elements(new.lines) loop
  select array_agg(k order by k) into keys from jsonb_object_keys(line) k;
  if not keys<@array['amountCents','description','markupBps','qtyMilli','unitCostCents'] then raise exception 'Invalid change line fields' using errcode='22023';end if;
  if line?'qtyMilli' and (jsonb_typeof(line->'qtyMilli') is distinct from 'number' or (line->>'qtyMilli')::numeric<>round((line->>'qtyMilli')::numeric) or (line->>'qtyMilli')::numeric not between 1 and 1000000000) then raise exception 'Invalid change quantity' using errcode='22023';end if;
  if line?'unitCostCents' and (jsonb_typeof(line->'unitCostCents') is distinct from 'number' or (line->>'unitCostCents')::numeric<>round((line->>'unitCostCents')::numeric) or (line->>'unitCostCents')::numeric not between 0 and 10000000000) then raise exception 'Invalid change cost' using errcode='22023';end if;
  if line?'markupBps' and (jsonb_typeof(line->'markupBps') is distinct from 'number' or (line->>'markupBps')::numeric<>round((line->>'markupBps')::numeric) or (line->>'markupBps')::numeric not between 0 and 100000) then raise exception 'Invalid change markup' using errcode='22023';end if;
  if (line?'qtyMilli' or line?'unitCostCents' or line?'markupBps') and not(line?'qtyMilli' and line?'unitCostCents' and line?'markupBps') then raise exception 'Quantity, cost and markup go together' using errcode='22023';end if;
  if line?'qtyMilli' then
   q:=(line->>'qtyMilli')::numeric;cost:=(line->>'unitCostCents')::numeric;markup:=(line->>'markupBps')::numeric;
   expected:=round(q*cost*(10000+markup)/10000000);
   if abs((line->>'amountCents')::numeric)<>expected then raise exception 'Change line amount does not match quantity, cost and markup' using errcode='22023';end if;
  end if;
 end loop;
 return new;
end $$;
drop trigger if exists pro_work_change_lines_guard on public.pro_work_changes;
create trigger pro_work_change_lines_guard before insert on public.pro_work_changes for each row execute function public.pro_work_change_lines_guard();

-- The propose input is kept (immutable) in pro_work_change_actions; its scheduleDays goes to the row.
create or replace function public.pro_work_change_schedule_days() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare days numeric;
begin
 if new.input->>'action'<>'propose' or not(new.input?'scheduleDays') then return new;end if;
 if jsonb_typeof(new.input->'scheduleDays') is distinct from 'number' then raise exception 'Invalid schedule impact' using errcode='22023';end if;
 days:=(new.input->>'scheduleDays')::numeric;
 if days<>round(days) or days not between 0 and 365 then raise exception 'Invalid schedule impact' using errcode='22023';end if;
 update public.pro_work_changes set schedule_days=days::integer where owner_id=new.owner_id and id=(new.input->>'id')::uuid and status='proposed' and schedule_days=0;
 return new;
end $$;
drop trigger if exists pro_work_change_schedule_days on public.pro_work_change_actions;
create trigger pro_work_change_schedule_days after insert on public.pro_work_change_actions for each row execute function public.pro_work_change_schedule_days();

-- Acceptance moves the plan once: the tasks that finish last are extended by the days.
create or replace function public.pro_work_change_apply_schedule() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare last_end date;shifted integer:=0;
begin
 if new.status<>'accepted' or old.status='accepted' or new.schedule_days=0 or new.schedule_applied_at is not null then return new;end if;
 select max(planned_end) into last_end from public.pro_work_schedule_plans where owner_id=new.owner_id and work_id=new.work_id and planned_end is not null;
 if last_end is not null and last_end+new.schedule_days<=date'2100-12-31' then
  update public.pro_work_schedule_plans set planned_end=planned_end+new.schedule_days where owner_id=new.owner_id and work_id=new.work_id and planned_end=last_end;
  get diagnostics shifted=row_count;
  update public.pro_work_schedule_heads set revision=revision+1,updated_at=now() where owner_id=new.owner_id and work_id=new.work_id;
 end if;
 new.schedule_applied_at:=now();new.schedule_shifted_tasks:=shifted;
 return new;
end $$;
drop trigger if exists pro_work_change_apply_schedule on public.pro_work_changes;
create trigger pro_work_change_apply_schedule before update on public.pro_work_changes for each row execute function public.pro_work_change_apply_schedule();

-- Days and the applied shift are immutable once written.
create or replace function public.pro_work_change_schedule_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.schedule_days<>0 and new.schedule_days is distinct from old.schedule_days then raise exception 'Schedule impact is immutable' using errcode='22023';end if;
 if old.schedule_applied_at is not null and (new.schedule_applied_at is distinct from old.schedule_applied_at or new.schedule_shifted_tasks is distinct from old.schedule_shifted_tasks) then raise exception 'Schedule impact is immutable' using errcode='22023';end if;
 if old.status<>'proposed' and new.schedule_days is distinct from old.schedule_days then raise exception 'Schedule impact is immutable' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_work_change_schedule_immutable on public.pro_work_changes;
create trigger pro_work_change_schedule_immutable before update on public.pro_work_changes for each row execute function public.pro_work_change_schedule_immutable();

-- Reader for the change list (owner and linked customer): days and applied shift per change.
create or replace function public.pro_work_change_schedule_read(p_actor uuid,p_ids uuid[]) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_object_agg(c.id::text,jsonb_build_object('scheduleDays',c.schedule_days,'scheduleApplied',c.schedule_applied_at is not null,'shiftedTasks',c.schedule_shifted_tasks)),'{}'::jsonb)
 from public.pro_work_changes c where c.id=any(coalesce(p_ids,'{}'::uuid[])) and cardinality(coalesce(p_ids,'{}'::uuid[]))<=50 and p_actor in(c.owner_id,c.client_user_id);
$$;
revoke all on function public.pro_work_change_lines_guard(),public.pro_work_change_schedule_days(),public.pro_work_change_apply_schedule(),public.pro_work_change_schedule_immutable(),public.pro_work_change_schedule_read(uuid,uuid[]) from public,anon,authenticated;
grant execute on function public.pro_work_change_schedule_read(uuid,uuid[]) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== team-roles-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): company team roles (Administrador, Gerente, Miembro,
-- Solo lectura) enforced on the server, email invitations as mock drafts (never sent) and lead
-- assignment («Asignado a»).
--
-- Model. The owner (the Pro account) is Administrator implicitly and is never a row here. A company
-- member is a registered account that accepted an invitation code. While a member works «in» the
-- owner's company, every /api/pro request goes through ONE gate (middleware → pro_team_route_authorize)
-- which maps the request to a capability and asks the single helper pro_role_require(); allowed
-- requests run as the owner's workspace, denied writes get 42501 → 403. The matrix lives only in
-- pro_role_allows(). Allowed writes are recorded (append-only) with the member's identity.
-- Per-job collaborators of team-local.sql (viewer/contributor grants) are unchanged.
--
-- Patterns: RLS on, service_role-only grants, security invoker, CAS revision (40001), idempotent
-- actionId receipts, immutable history, America/Costa_Rica dates. No email is sent; the invitation
-- email is stored as a draft for the owner to copy.
begin;

create table if not exists public.pro_company_members(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null default gen_random_uuid(),
 member_user_id uuid not null references public.profiles(id) on delete cascade,
 member_name text not null default '' check(length(member_name)<=160),
 member_email text not null default '' check(length(member_email)<=254),
 role text not null check(role in('admin','manager','member','read_only')),
 active boolean not null default true,
 revision integer not null default 1 check(revision>0),
 source_invite_id uuid,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id),unique(owner_id,member_user_id),check(owner_id<>member_user_id));
create index if not exists pro_company_members_member_idx on public.pro_company_members(member_user_id) where active;

create table if not exists public.pro_company_invites(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 email text not null check(length(email) between 3 and 254 and email=lower(btrim(email))),
 role text not null check(role in('admin','manager','member','read_only')),
 token_sha256 text not null unique check(token_sha256~'^[a-f0-9]{64}$'),
 status text not null default 'pending' check(status in('pending','accepted','cancelled')),
 revision integer not null default 1 check(revision>0),
 expires_at timestamptz not null,
 -- Mock delivery: the email is only drafted here; nothing is sent.
 delivery text not null default 'draft_not_sent' check(delivery='draft_not_sent'),
 draft_subject text not null check(length(draft_subject) between 1 and 200),
 draft_body text not null check(length(draft_body) between 1 and 4000),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,id));

create table if not exists public.pro_company_team_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input_hash text not null check(input_hash~'^[a-f0-9]{32}$'),result jsonb not null,
 at timestamptz not null default now(),primary key(actor_id,action_id));

create table if not exists public.pro_company_team_events(
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references public.profiles(id) on delete cascade,
 actor_id uuid not null,actor_name text not null default '',action_id uuid not null,
 action text not null check(action in('invite','cancel_invite','accept','set_role','remove','leave')),
 member_id uuid,invite_id uuid,before_state jsonb,after_state jsonb,at timestamptz not null default now());
create index if not exists pro_company_team_events_owner_idx on public.pro_company_team_events(owner_id,at desc,id desc);

-- Writes a member made in the owner's company (who, what, when). Append-only.
create table if not exists public.pro_company_team_activity(
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references public.profiles(id) on delete cascade,
 member_user_id uuid not null,member_name text not null default '',role text not null,
 capability text not null,method text not null,path text not null check(length(path)<=200),
 at timestamptz not null default now());
create index if not exists pro_company_team_activity_owner_idx on public.pro_company_team_activity(owner_id,at desc);

create table if not exists public.pro_lead_assignments(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 kind text not null check(kind in('manual','request')),lead_id uuid not null,
 assignee_id uuid references public.profiles(id) on delete set null,
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(owner_id,kind,lead_id));
create index if not exists pro_lead_assignments_assignee_idx on public.pro_lead_assignments(owner_id,assignee_id);
create table if not exists public.pro_lead_assignment_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 kind text not null,lead_id uuid not null,action_id uuid not null,
 before_assignee uuid,after_assignee uuid,revision integer not null,at timestamptz not null default now(),
 primary key(owner_id,action_id));
create table if not exists public.pro_lead_assignment_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default now(),
 primary key(owner_id,action_id));

-- ── The permission matrix (single source) ──────────────────────────────────────────────────────
create or replace function public.pro_role_allows(p_role text,p_capability text) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_role
  when 'admin' then p_capability in('read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage')
  when 'manager' then p_capability in('read','work.write','lead.write','sales.write','finance.write','company.write')
  when 'member' then p_capability in('read','work.write','lead.write')
  when 'read_only' then p_capability='read'
  else false end
$$;
create or replace function public.pro_role_matrix_read() returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_object_agg(r,(select jsonb_agg(c order by o) from unnest(array['read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage']) with ordinality x(c,o) where public.pro_role_allows(r,c)))
 from unnest(array['admin','manager','member','read_only']) r
$$;

-- Role of p_actor in p_owner's company: the owner is admin; an active member has its row's role.
create or replace function public.pro_role_of(p_actor uuid,p_owner uuid) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_actor is null or p_owner is null then null when p_actor=p_owner then 'admin'
  else (select m.role from public.pro_company_members m join public.profiles p on p.id=m.member_user_id
        where m.owner_id=p_owner and m.member_user_id=p_actor and m.active and not coalesce(p.is_disabled,false)) end
$$;

-- THE helper: raises 42501 unless the actor's role in the owner's company allows the capability.
create or replace function public.pro_role_require(p_actor uuid,p_owner uuid,p_capability text) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r text;
begin
 if p_capability is null or p_capability not in('read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage') then raise exception 'Unknown capability' using errcode='22023';end if;
 r:=public.pro_role_of(p_actor,p_owner);
 if r is null or not public.pro_role_allows(r,p_capability) then raise exception 'Role does not allow %',p_capability using errcode='42501';end if;
 return r;
end $$;

-- Capability of one /api/pro request (method + path). Reads are 'read'; writes by module.
create or replace function public.pro_role_route_capability(p_method text,p_path text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare seg text:=split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1);
begin
 if upper(coalesce(p_method,'')) in('GET','HEAD','OPTIONS') then return 'read';end if;
 if seg in('team','team-roles') then return 'team.manage';end if;
 if seg ~ '^(integrations|connectors|oauth|site|site-public|marketing|marketing-confirm|ads-tracking|social|social-content|promotions|invoice-document-settings|invoice-issuer|accounting|accounting-export|einvoice|einvoice-file)$' then return 'settings.write';end if;
 if seg ~ '^(invoice-|payment-|pay$|client-operations|client-balance|client-statement|client-finances|credits-retainers|work-billing|work-budget|work-costs|expenses|expense-receipts|purchase-order|online-payments)' then return 'finance.write';end if;
 if seg ~ '^(lead-|request-pipeline|request-followups|manual-lead-)' then return 'lead.write';end if;
 if seg ~ '^(private-estimate|quote|quotes|contract|esign|appointment-|reservations|bids|bid-portal-links|work-changes|selections|allowances|project-quote-context|visit-preparation|work-client-invitations|client-dashboard|client-pending|client-fiscal|request-quotes|direct-project|workspace|projects|work-header|identity-lookup)' then return 'sales.write';end if;
 if seg ~ '^(catalog|company-|service-packages|discount-presets|task-templates|schedule-templates|ai|ai-meetings)' then return 'company.write';end if;
 return 'work.write';
end $$;

-- Workspace a member may enter (null when not an active member or the owner lost Pro).
create or replace function public.pro_team_workspace_resolve(p_member uuid,p_owner uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r text;
begin
 if p_member is null or p_owner is null or p_member=p_owner then return null;end if;
 r:=public.pro_role_of(p_member,p_owner);
 if r is null or not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then return null;end if;
 return jsonb_build_object('ownerId',p_owner,'ownerName',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=p_owner),public.pro_team_name(p_owner)),
  'role',r,'capabilities',(select jsonb_agg(c) from unnest(array['read','work.write','lead.write','sales.write','finance.write','company.write','settings.write','team.manage']) c where public.pro_role_allows(r,c)));
end $$;

-- The gate called once per /api/pro request of a member working in another company.
create or replace function public.pro_team_route_authorize(p_member uuid,p_owner uuid,p_method text,p_path text) returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare ws jsonb;cap text;
begin
 if p_path is null or length(p_path)>200 or p_path !~ '^/api/pro(/|$)' then raise exception 'Invalid route' using errcode='22023';end if;
 ws:=public.pro_team_workspace_resolve(p_member,p_owner);
 if ws is null then return jsonb_build_object('allowed',false,'reason','not_member');end if;
 cap:=public.pro_role_route_capability(p_method,p_path);
 begin perform public.pro_role_require(p_member,p_owner,cap);
 exception when insufficient_privilege then return jsonb_build_object('allowed',false,'reason','role','role',ws->>'role','capability',cap);end;
 if cap<>'read' then
  insert into public.pro_company_team_activity(owner_id,member_user_id,member_name,role,capability,method,path)
  values(p_owner,p_member,public.pro_team_name(p_member),ws->>'role',cap,upper(p_method),left(p_path,200));
 end if;
 return jsonb_build_object('allowed',true,'role',ws->>'role','capability',cap);
end $$;

create or replace function public.pro_company_member_json(m public.pro_company_members) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',m.id,'userId',m.member_user_id,'name',m.member_name,'email',m.member_email,'role',m.role,'active',m.active,'revision',m.revision,'since',m.created_at)
$$;
create or replace function public.pro_company_invite_json(i public.pro_company_invites) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',i.id,'email',i.email,'role',i.role,'status',case when i.status='pending' and i.expires_at<=now() then 'expired' else i.status end,'revision',i.revision,'expiresAt',i.expires_at,'delivery',i.delivery,'draft',jsonb_build_object('subject',i.draft_subject,'body',i.draft_body),'createdAt',i.created_at)
$$;

-- Owner view (or an admin member, through the gate as the owner) + the companies the actor belongs to.
create or replace function public.pro_company_team_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare members jsonb;invites jsonb;events jsonb;memberships jsonb;activity jsonb;owner boolean:=coalesce(public.pro_private_work_tools_enabled(p_actor),false);
begin
 select coalesce(jsonb_agg(jsonb_build_object('ownerId',m.owner_id,'memberId',m.id,'revision',m.revision,'role',m.role,'ownerName',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=m.owner_id),public.pro_team_name(m.owner_id))) order by m.created_at),'[]'::jsonb)
  into memberships from public.pro_company_members m where m.member_user_id=p_actor and m.active and coalesce(public.pro_private_work_tools_enabled(m.owner_id),false);
 if not owner then return jsonb_build_object('isOwner',false,'members','[]'::jsonb,'invites','[]'::jsonb,'events','[]'::jsonb,'activity','[]'::jsonb,'memberships',memberships,'matrix',public.pro_role_matrix_read());end if;
 select coalesce(jsonb_agg(public.pro_company_member_json(m) order by m.active desc,lower(m.member_name),m.id),'[]'::jsonb) into members from public.pro_company_members m where m.owner_id=p_actor;
 select coalesce(jsonb_agg(public.pro_company_invite_json(i) order by i.created_at desc),'[]'::jsonb) into invites from (select * from public.pro_company_invites where owner_id=p_actor order by created_at desc limit 50) i;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'action',e.action,'actorName',e.actor_name,'at',e.at,'after',e.after_state) order by e.at desc,e.id desc),'[]'::jsonb) into events from (select * from public.pro_company_team_events where owner_id=p_actor order by at desc,id desc limit 30) e;
 select coalesce(jsonb_agg(jsonb_build_object('memberName',a.member_name,'role',a.role,'capability',a.capability,'path',a.path,'at',a.at) order by a.at desc),'[]'::jsonb) into activity from (select * from public.pro_company_team_activity where owner_id=p_actor order by at desc limit 30) a;
 return jsonb_build_object('isOwner',true,'ownerId',p_actor,'members',members,'invites',invites,'events',events,'activity',activity,'memberships',memberships,'matrix',public.pro_role_matrix_read());
end $$;

-- Options of «Asignado a»: the owner plus active company members.
create or replace function public.pro_lead_assignees_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_array(jsonb_build_object('userId',p_actor,'name',coalesce(nullif(public.pro_team_name(p_actor),''),'Administrador'),'role','admin'))||
  coalesce((select jsonb_agg(jsonb_build_object('userId',m.member_user_id,'name',coalesce(nullif(m.member_name,''),m.member_email),'role',m.role) order by lower(m.member_name)) from public.pro_company_members m where m.owner_id=p_actor and m.active),'[]'::jsonb);
end $$;

create or replace function public.pro_company_team_mutate(p_actor uuid,p_input jsonb,p_verified_email text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;owner uuid;keys text[];hash text;prior public.pro_company_team_actions;m public.pro_company_members;i public.pro_company_invites;
 role_wanted text;email text;answer jsonb;before_state jsonb;after_state jsonb;en boolean:=coalesce(p_input->>'locale','es')='en';company text;
begin
 if act is null or act not in('invite','cancel_invite','accept','set_role','remove','leave') or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid team action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 hash:=md5(p_input::text);
 select * into prior from public.pro_company_team_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if act='invite' then
  if keys<>array['action','actionId','codeHash','email','locale','role'] then raise exception 'Invalid invitation fields' using errcode='22023';end if;
  owner:=p_actor;perform public.pro_role_require(p_actor,owner,'team.manage');
  if not coalesce(public.pro_private_work_tools_enabled(owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
  email:=p_input->>'email';role_wanted:=p_input->>'role';
  if email is null or email<>lower(btrim(email)) or length(email)>254 or email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or role_wanted not in('admin','manager','member','read_only') or coalesce(p_input->>'codeHash','') !~ '^[a-f0-9]{64}$' or p_input->>'locale' not in('es','en') then raise exception 'Invalid invitation' using errcode='22023';end if;
  if (select count(*) from public.pro_company_invites where owner_id=owner and status='pending' and expires_at>now())>=50 then raise exception 'Too many invitations' using errcode='54000';end if;
  company:=coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=owner),nullif(public.pro_team_name(owner),''),'ContrataCR Pro');
  insert into public.pro_company_invites(owner_id,id,email,role,token_sha256,expires_at,draft_subject,draft_body)
  values(owner,aid,email,role_wanted,p_input->>'codeHash',now()+interval '72 hours',
   case when en then 'Invitation to join '||company||' on ContrataCR Pro' else 'Invitación para unirse a '||company||' en ContrataCR Pro' end,
   case when en then 'Hello,'||chr(10)||chr(10)||company||' invites you to its team on ContrataCR Pro as '||(case role_wanted when 'admin' then 'Administrator' when 'manager' then 'Manager' when 'member' then 'Member' else 'Read-only' end)||'.'||chr(10)||'Sign in with this email, open Pro › Team › «Join a company» and enter the code you will receive separately. The code expires in 72 hours.'
    else 'Hola:'||chr(10)||chr(10)||company||' le invita a su equipo en ContrataCR Pro como '||(case role_wanted when 'admin' then 'Administrador' when 'manager' then 'Gerente' when 'member' then 'Miembro' else 'Solo lectura' end)||'.'||chr(10)||'Inicie sesión con este correo, abra Pro › Equipo › «Unirse a una empresa» e ingrese el código que recibirá por separado. El código vence en 72 horas.' end)
  returning * into i;
  after_state:=public.pro_company_invite_json(i);answer:=jsonb_build_object('invite',after_state);
 elsif act='cancel_invite' then
  if keys<>array['action','actionId','inviteId','revision'] then raise exception 'Invalid fields' using errcode='22023';end if;
  owner:=p_actor;perform public.pro_role_require(p_actor,owner,'team.manage');
  select * into i from public.pro_company_invites where owner_id=owner and id=(p_input->>'inviteId')::uuid for update;
  if not found then raise exception 'Invitation unavailable' using errcode='P0002';end if;
  if i.revision<>(p_input->>'revision')::integer or i.status<>'pending' then raise exception 'Invitation changed' using errcode='40001';end if;
  before_state:=public.pro_company_invite_json(i);
  update public.pro_company_invites set status='cancelled',revision=revision+1,updated_at=now() where owner_id=owner and id=i.id returning * into i;
  after_state:=public.pro_company_invite_json(i);answer:=jsonb_build_object('invite',after_state);
 elsif act='accept' then
  if keys<>array['action','actionId','codeHash'] or coalesce(p_input->>'codeHash','') !~ '^[a-f0-9]{64}$' then raise exception 'Invalid code' using errcode='22023';end if;
  select * into i from public.pro_company_invites where token_sha256=p_input->>'codeHash' for update;
  if not found or i.status<>'pending' or i.expires_at<=now() then raise exception 'Invitation unavailable' using errcode='P0002';end if;
  if p_verified_email is null or lower(btrim(p_verified_email))<>i.email then raise exception 'Invitation is for another email' using errcode='42501';end if;
  if i.owner_id=p_actor then raise exception 'Owner cannot join own company' using errcode='22023';end if;
  owner:=i.owner_id;
  select * into m from public.pro_company_members where owner_id=owner and member_user_id=p_actor for update;
  if found then before_state:=public.pro_company_member_json(m);
   update public.pro_company_members set role=i.role,active=true,revision=revision+1,source_invite_id=i.id,member_name=public.pro_team_name(p_actor),member_email=i.email,updated_at=now() where owner_id=owner and id=m.id returning * into m;
  else insert into public.pro_company_members(owner_id,member_user_id,member_name,member_email,role,source_invite_id) values(owner,p_actor,public.pro_team_name(p_actor),i.email,i.role,i.id) returning * into m;end if;
  update public.pro_company_invites set status='accepted',revision=revision+1,updated_at=now() where owner_id=owner and id=i.id;
  after_state:=public.pro_company_member_json(m);answer:=jsonb_build_object('member',after_state,'ownerId',owner);
 else
  if act='leave' and keys<>array['action','actionId','memberId','ownerId','revision'] or act='remove' and keys<>array['action','actionId','memberId','revision'] or act='set_role' and keys<>array['action','actionId','memberId','revision','role'] then raise exception 'Invalid fields' using errcode='22023';end if;
  if act='leave' then owner:=(p_input->>'ownerId')::uuid;else owner:=p_actor;perform public.pro_role_require(p_actor,owner,'team.manage');end if;
  select * into m from public.pro_company_members where owner_id=owner and id=(p_input->>'memberId')::uuid for update;
  if not found or act='leave' and m.member_user_id<>p_actor then raise exception 'Member unavailable' using errcode='P0002';end if;
  if m.revision<>(p_input->>'revision')::integer then raise exception 'Member changed' using errcode='40001';end if;
  if act='set_role' then role_wanted:=p_input->>'role';if role_wanted is null or role_wanted not in('admin','manager','member','read_only') or not m.active then raise exception 'Invalid role' using errcode='22023';end if;end if;
  before_state:=public.pro_company_member_json(m);
  update public.pro_company_members set role=coalesce(role_wanted,role),active=act='set_role',revision=revision+1,updated_at=now() where owner_id=owner and id=m.id returning * into m;
  after_state:=public.pro_company_member_json(m);answer:=jsonb_build_object('member',after_state);
 end if;
 insert into public.pro_company_team_events(owner_id,actor_id,actor_name,action_id,action,member_id,invite_id,before_state,after_state)
 values(owner,p_actor,public.pro_team_name(p_actor),aid,act,case when act in('invite','cancel_invite') then null else (after_state->>'id')::uuid end,case when act in('invite','cancel_invite') then i.id when act='accept' then i.id end,before_state,after_state);
 insert into public.pro_company_team_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- ── Lead assignment ────────────────────────────────────────────────────────────────────────────
create or replace function public.pro_lead_assign(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;k text:=p_input->>'kind';lid uuid;who uuid;before_who uuid;rev integer;cur public.pro_lead_assignments;prior public.pro_lead_assignment_actions;hash text:=md5(p_input::text);keys text[];answer jsonb;
begin
 select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys<>array['actionId','assigneeId','id','kind','revision'] or k not in('manual','request') or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid assignment' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;who:=nullif(p_input->>'assigneeId','')::uuid;exception when others then raise exception 'Invalid assignment' using errcode='22023';end;
 rev:=(p_input->>'revision')::integer;
 select * into prior from public.pro_lead_assignment_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 perform public.pro_lead_center_item(p_actor,k,lid);
 if who is not null and who<>p_actor and not exists(select 1 from public.pro_company_members where owner_id=p_actor and member_user_id=who and active) then raise exception 'Assignee is not on the team' using errcode='22023';end if;
 select * into cur from public.pro_lead_assignments where owner_id=p_actor and kind=k and lead_id=lid for update;
 if coalesce(cur.revision,0)<>rev then raise exception 'Assignment changed' using errcode='40001';end if;
 before_who:=cur.assignee_id;
 if found then update public.pro_lead_assignments set assignee_id=who,revision=revision+1,updated_at=now() where owner_id=p_actor and kind=k and lead_id=lid returning * into cur;
 else insert into public.pro_lead_assignments(owner_id,kind,lead_id,assignee_id) values(p_actor,k,lid,who) returning * into cur;end if;
 insert into public.pro_lead_assignment_history(owner_id,kind,lead_id,action_id,before_assignee,after_assignee,revision) values(p_actor,k,lid,aid,before_who,who,cur.revision);
 answer:=jsonb_build_object('kind',k,'id',lid,'assigneeId',cur.assignee_id,'revision',cur.revision);
 insert into public.pro_lead_assignment_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- Leads list (the inbox reader of lead-inboxes-local.sql, same contract: cursor + snapshot token)
-- filtered by assignee BEFORE paging ('unassigned' or an account id), plus each listed lead's
-- assignment. A separate name so the original reader keeps its exact signature.
create or replace function public.pro_lead_inbox_read_assigned(p_actor uuid,p_box text default 'active',p_stage text default null,p_query text default '',p_service text default null,p_channel text default null,p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null,p_assignee text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;service_key text:=lower(btrim(coalesce(p_service,'')));who uuid;begin
 if p_assignee is not null and p_assignee<>'unassigned' then begin who:=p_assignee::uuid;exception when others then raise exception 'Invalid assignee' using errcode='22023';end;end if;
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_box is null or p_box not in('active','snoozed','archived') or p_query is null or length(p_query)>100 or length(coalesce(p_service,''))>160 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' or (p_after is null)<>(p_snapshot is null) or p_from is not null and p_from not between date'1900-01-01' and date'2100-12-31' or p_to is not null and p_to not between date'1900-01-01' and date'2100-12-31' or p_from>p_to then raise exception 'Invalid inbox query' using errcode='22023';end if;
 if p_channel is not null and p_channel<>'unspecified' and pro_lead_origin_channel_json(p_actor,p_channel) is null then raise exception 'Invalid attribution filter' using errcode='22023';end if;
 with base as materialized(select * from pro_lead_inbox_sources(p_actor,p_query)),
 filtered as materialized(select b.*,case when b.archived then 'archived' when b.snoozed then 'snoozed' else 'active' end box from base b where(service_key='' or lower(b.service_label)=service_key) and(p_channel is null or p_channel='unspecified' and b.channel_id is null or b.channel_id=p_channel) and(p_from is null or b.created_day>=p_from) and(p_to is null or b.created_day<=p_to)
   and(p_assignee is null or (select a.assignee_id from pro_lead_assignments a where a.owner_id=p_actor and a.kind=b.kind and a.lead_id=b.id) is not distinct from who)),
 sources as materialized(select * from filtered where box=p_box),
 metadata as(select md5(p_actor::text||coalesce(p_assignee,'any')||p_box||coalesce(p_stage,'all')||p_query||service_key||coalesce(p_channel,'all')||coalesce(p_from::text,'')||coalesce(p_to::text,'')||pro_lead_inbox_today()::text||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c) order by c.id)::text,'[]') from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived,snooze_revision)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items,
  coalesce(jsonb_agg(pro_lead_commercial_progress(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)stages,
  coalesce(jsonb_agg(pro_lead_origin_get(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)context,
  coalesce(jsonb_agg(pro_lead_snooze_json(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)snoozes,
  coalesce(jsonb_object_agg(kind||':'||id::text,jsonb_build_object('assigneeId',(select a.assignee_id from pro_lead_assignments a where a.owner_id=p_actor and a.kind=v.kind and a.lead_id=v.id),'revision',coalesce((select a.revision from pro_lead_assignments a where a.owner_id=p_actor and a.kind=v.kind and a.lead_id=v.id),0))),'{}'::jsonb)assignments
  from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s),
 inbox as(select jsonb_build_object('active',(select count(*) from filtered where box='active'),'snoozed',(select count(*) from filtered where box='snoozed'),'archived',(select count(*) from filtered where box='archived'),'imports',(select count(*) from pro_lead_imports where owner_id=p_actor),
  'stages',(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from filtered f where f.box='active' and f.effective_stage=s->>'id')) order by(s->>'position')::integer) from jsonb_array_elements(catalog->'stages')s))v),
 services as(select coalesce(jsonb_agg(label order by lower(label),label),'[]'::jsonb)v from(select min(service_label)label from base where service_label<>'' group by lower(service_label) order by lower(min(service_label)) limit 100)x)
 select jsonb_build_object('page',jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),
  'stages',page.stages,'context',page.context,'snoozes',page.snoozes,'assignments',page.assignments,'inboxes',inbox.v,'services',services.v),metadata.token,(p_after is null or exists(select 1 from anchor))
 into answer,actual_token,cursor_valid from page cross join counts cross join metadata cross join inbox cross join services;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return answer;end $$;

create or replace function public.pro_company_team_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Immutable team history' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_company_members','pro_company_invites','pro_company_team_actions','pro_company_team_events','pro_company_team_activity','pro_lead_assignments','pro_lead_assignment_history','pro_lead_assignment_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_company_team_actions','pro_company_team_events','pro_company_team_activity','pro_lead_assignment_history','pro_lead_assignment_actions'] loop
  execute format('drop trigger if exists pro_company_team_immutable on public.%I',t);execute format('create trigger pro_company_team_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_company_team_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_role_allows','pro_role_matrix_read','pro_role_of','pro_role_require','pro_role_route_capability','pro_team_workspace_resolve','pro_team_route_authorize','pro_company_member_json','pro_company_invite_json','pro_company_team_read','pro_lead_assignees_read','pro_company_team_mutate','pro_lead_assign','pro_lead_inbox_read_assigned','pro_company_team_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== work-journal-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): one Daily Log («Bitácora») per job.
-- «Avances» (pro_work_updates) and «Resumen del día» (pro_daily_logs) become ONE list of entries:
-- the daily log row is the entry (date, notes, photos, optional weather) and gains a crew/hours
-- summary and a «Visible al cliente» switch. The customer sees only visible entries.
-- Migration: every existing avance gets exactly one daily log entry (same date in Costa Rica, title
-- and text; visible when it had been shared with the customer); every daily log already shared
-- with a customer becomes visible. Nothing is deleted: pro_work_updates and its immutable history
-- and published versions stay as they were (link: pro_daily_logs.source_update_id). A trigger keeps
-- new avances (old API) mirrored once. Patterns: RLS, service_role-only, security invoker, CAS
-- (40001), idempotent actionId receipts (pro_daily_log_actions), immutable history.
begin;
alter table public.pro_daily_logs add column if not exists client_visible boolean not null default false;
alter table public.pro_daily_logs add column if not exists crew_count smallint;
alter table public.pro_daily_logs add column if not exists crew_minutes integer;
alter table public.pro_daily_logs add column if not exists source_update_id uuid;
do $$begin
 if not exists(select 1 from pg_constraint where conname='pro_daily_logs_crew_check') then
  alter table public.pro_daily_logs add constraint pro_daily_logs_crew_check check((crew_count is null or crew_count between 0 and 500) and (crew_minutes is null or crew_minutes between 0 and 600000));end if;
end $$;
create unique index if not exists pro_daily_logs_source_update_idx on public.pro_daily_logs(owner_id,source_update_id) where source_update_id is not null;

-- Deterministic entry id for an avance (UUID v4 layout from md5).
create or replace function public.pro_work_journal_entry_id(p_update uuid) returns uuid language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-'||substr('89ab',(('x'||substr(h,17,1))::bit(4)::int%4)+1,1)||substr(h,18,3)||'-'||substr(h,21,12))::uuid from (select md5('pro-work-journal:'||p_update::text) h) x
$$;

-- Copies one avance into the daily log once (no-op when already copied or the job is gone).
create or replace function public.pro_work_journal_copy_update(p_owner uuid,p_update uuid) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare u public.pro_work_updates;lid uuid;day date;snap jsonb;name text;l public.pro_daily_logs;
begin
 select * into u from public.pro_work_updates where owner_id=p_owner and id=p_update;
 if not found then return null;end if;
 if exists(select 1 from public.pro_daily_logs where owner_id=p_owner and source_update_id=p_update) then return null;end if;
 lid:=public.pro_work_journal_entry_id(p_update);day:=(u.created_at at time zone 'America/Costa_Rica')::date;
 snap:=jsonb_build_object('date',to_char(day,'YYYY-MM-DD'),'tasks','[]'::jsonb,'plan','[]'::jsonb,'minutes',null,'fingerprint',md5('pro-work-journal:'||p_update::text));
 name:=coalesce(nullif(public.pro_team_name(p_owner),''),'Pro');
 insert into public.pro_daily_logs(owner_id,work_id,id,log_date,title,summary,sections,weather,snapshot,revision,created_by,created_by_name,created_at,updated_at,client_visible,source_update_id)
 values(p_owner,u.work_id,lid,day,left(btrim(u.title),160),left(u.text,2000),'{"plan":false,"tasks":false,"time":false,"weather":false}'::jsonb,null,snap,1,p_owner,left(name,160),u.created_at,u.updated_at,u.published_revision is not null,p_update)
 on conflict do nothing returning * into l;
 if l.id is null then return null;end if;
 insert into public.pro_daily_log_history(owner_id,work_id,log_id,action_id,actor_id,actor_name,action,before_log,after_log,at)
 values(p_owner,u.work_id,lid,public.pro_work_journal_entry_id(lid),p_owner,left(name,160),'create',null,public.pro_daily_log_json(l)||jsonb_build_object('migratedFromUpdate',p_update),u.created_at);
 return lid;
end $$;

-- One-time migration of existing rows of both modules (a marker keeps a reinstall from changing
-- anything; later rows are kept in step by the two triggers below).
create table if not exists public.pro_work_journal_migrations(step text primary key,at timestamptz not null default now());
alter table public.pro_work_journal_migrations enable row level security;
revoke all on public.pro_work_journal_migrations from public,anon,authenticated;
grant select,insert on public.pro_work_journal_migrations to service_role;
do $$declare u record;begin
 if exists(select 1 from public.pro_work_journal_migrations where step='updates-and-daily-logs-v1') then return;end if;
 for u in select owner_id,id from public.pro_work_updates order by created_at,id loop perform public.pro_work_journal_copy_update(u.owner_id,u.id);end loop;
 update public.pro_daily_logs l set client_visible=true where not l.client_visible and exists(select 1 from public.pro_daily_log_audiences a where a.owner_id=l.owner_id and a.work_id=l.work_id and a.log_id=l.id and a.kind='client');
 insert into public.pro_work_journal_migrations(step) values('updates-and-daily-logs-v1');
end $$;
-- Snapshot shape of the daily log reader ({date,tasks,plan,minutes,fingerprint}); repairs entries copied
-- by an earlier draft of this module that used a «time» key (idempotent, no-op once repaired).
update public.pro_daily_logs set snapshot=(snapshot-'time')||jsonb_build_object('minutes',null) where source_update_id is not null and snapshot ? 'time';
-- A daily log shared with a customer through the existing publication is visible to that customer.
create or replace function public.pro_work_journal_publication_visible() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin if new.kind='client' then update public.pro_daily_logs set client_visible=true where owner_id=new.owner_id and work_id=new.work_id and id=new.log_id and not client_visible;end if;return new;end $$;
drop trigger if exists pro_work_journal_publication_visible on public.pro_daily_log_audiences;
create trigger pro_work_journal_publication_visible after insert on public.pro_daily_log_audiences for each row execute function public.pro_work_journal_publication_visible();

create or replace function public.pro_work_journal_mirror() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin perform public.pro_work_journal_copy_update(new.owner_id,new.id);
 -- Shared again (published revision advanced): the entry shows what the customer was given. A private
 -- edit (no new publication) never reaches the visible entry.
 if tg_op='UPDATE' and new.published_revision is not null and new.published_revision is distinct from old.published_revision then
  update public.pro_daily_logs set client_visible=true,title=left(btrim(new.title),160),summary=left(new.text,2000),revision=revision+1,updated_at=now() where owner_id=new.owner_id and source_update_id=new.id;
 end if;
 return new;end $$;
drop trigger if exists pro_work_journal_mirror on public.pro_work_updates;
create trigger pro_work_journal_mirror after insert or update on public.pro_work_updates for each row execute function public.pro_work_journal_mirror();

-- Owner: journal fields of the job's entries (visible, crew, origin) to show beside each entry.
create or replace function public.pro_work_journal_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 return jsonb_build_object('workId',p_work,'entries',coalesce((select jsonb_object_agg(l.id::text,jsonb_build_object('clientVisible',l.client_visible,'crewCount',l.crew_count,'crewMinutes',l.crew_minutes,'fromUpdate',l.source_update_id is not null,'revision',l.revision)) from public.pro_daily_logs l where l.owner_id=p_actor and l.work_id=p_work),'{}'::jsonb),
  'visibleCount',(select count(*) from public.pro_daily_logs where owner_id=p_actor and work_id=p_work and client_visible and not archived),
  'migratedUpdates',(select count(*) from public.pro_daily_logs where owner_id=p_actor and work_id=p_work and source_update_id is not null));
end $$;

-- Owner write: «Visible al cliente» + crew/hours summary of one entry (CAS on the entry revision).
create or replace function public.pro_work_journal_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;l public.pro_daily_logs;before_json jsonb;answer jsonb;keys text[];receipt public.pro_daily_log_actions;crew_c integer;crew_m integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['action','actionId','clientVisible','crewCount','crewMinutes','logId','revision','workId'] or p_input->>'action'<>'journal_set' or jsonb_typeof(p_input->'clientVisible')<>'boolean' or jsonb_typeof(p_input->'revision')<>'number' or jsonb_typeof(p_input->'crewCount') not in('number','null') or jsonb_typeof(p_input->'crewMinutes') not in('number','null') then raise exception 'Invalid journal fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;crew_c:=(p_input->>'crewCount')::integer;crew_m:=(p_input->>'crewMinutes')::integer;exception when others then raise exception 'Invalid journal fields' using errcode='22023';end;
 if crew_c is not null and crew_c not between 0 and 500 or crew_m is not null and crew_m not between 0 and 600000 then raise exception 'Invalid crew summary' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_daily_log_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 select * into l from public.pro_daily_logs where owner_id=p_actor and work_id=p_input->>'workId' and id=(p_input->>'logId')::uuid for update;
 if not found then raise exception 'Entry unavailable' using errcode='P0002';end if;
 if l.revision<>(p_input->>'revision')::integer then raise exception 'Entry changed' using errcode='40001';end if;
 if l.archived and (p_input->>'clientVisible')::boolean then raise exception 'Archived entries cannot be visible' using errcode='22023';end if;
 before_json:=public.pro_daily_log_json(l)||jsonb_build_object('clientVisible',l.client_visible,'crewCount',l.crew_count,'crewMinutes',l.crew_minutes);
 update public.pro_daily_logs set client_visible=(p_input->>'clientVisible')::boolean,crew_count=crew_c,crew_minutes=crew_m,revision=revision+1,updated_at=now() where owner_id=l.owner_id and work_id=l.work_id and id=l.id returning * into l;
 answer:=jsonb_build_object('logId',l.id,'workId',l.work_id,'revision',l.revision,'clientVisible',l.client_visible,'crewCount',l.crew_count,'crewMinutes',l.crew_minutes);
 insert into public.pro_daily_log_history(owner_id,work_id,log_id,action_id,actor_id,actor_name,action,before_log,after_log)
 values(l.owner_id,l.work_id,l.id,aid,p_actor,left(coalesce(public.pro_team_name(p_actor),''),160),'update',before_json,public.pro_daily_log_json(l)||jsonb_build_object('clientVisible',l.client_visible,'crewCount',l.crew_count,'crewMinutes',l.crew_minutes));
 insert into public.pro_daily_log_actions(actor_id,action_id,owner_id,work_id,input,result,before_state,after_state) values(p_actor,aid,l.owner_id,l.work_id,p_input,answer,before_json,answer);
 return answer;
end $$;

-- Customer of the job (linked request account): visible, non-archived entries only. Photos are
-- listed by id/name (JPEG ready files of that entry); notes and weather as written; crew summary.
create or replace function public.pro_client_journal_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null and status in('confirmed','completed');
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('workId',r.work_id,'items',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'date',to_char(l.log_date,'YYYY-MM-DD'),'title',l.title,'notes',l.summary,'weather',l.weather,'crewCount',l.crew_count,'crewMinutes',l.crew_minutes,'fromUpdate',l.source_update_id is not null,
   'photos',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'name',f.name) order by f.created_at,f.id) from public.pro_daily_log_files f where f.owner_id=l.owner_id and f.work_id=l.work_id and f.log_id=l.id and f.ready and f.mime_type='image/jpeg'),'[]'::jsonb))
   order by l.log_date desc,l.created_at desc,l.id) from (select * from public.pro_daily_logs d where d.owner_id=r.owner_id and d.work_id=r.work_id and d.client_visible and not d.archived
   -- formally shared versions are listed below with their conversation (pro_daily_logs_client_read)
   and not exists(select 1 from public.pro_daily_log_audiences au where au.owner_id=d.owner_id and au.work_id=d.work_id and au.log_id=d.id and au.kind='client' and au.recipient_id=p_actor and au.request_id=r.id)
   order by d.log_date desc,d.created_at desc limit 60) l),'[]'::jsonb));
end $$;
create or replace function public.pro_client_journal_photo(p_actor uuid,p_request uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;f public.pro_daily_log_files;
begin
 select * into r from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null and status in('confirmed','completed');
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select f2.* into f from public.pro_daily_log_files f2 join public.pro_daily_logs l on l.owner_id=f2.owner_id and l.work_id=f2.work_id and l.id=f2.log_id
  where f2.id=p_file and f2.owner_id=r.owner_id and f2.work_id=r.work_id and l.client_visible and not l.archived and f2.ready and f2.mime_type='image/jpeg';
 if not found then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_work_journal_publication_visible','pro_work_journal_entry_id','pro_work_journal_copy_update','pro_work_journal_mirror','pro_work_journal_read','pro_work_journal_mutate','pro_client_journal_read','pro_client_journal_photo') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== cost-entry-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): one «Registrar costo» form.
-- «Registrar gasto» in a job's Costs & payments now carries the same fields as «Nuevo gasto» in
-- Expenses: supplier, category, amount, VAT included, billable, payment method (+ receipt, uploaded
-- by the existing receipts route afterwards). This wrapper runs the existing job writer
-- (pro_work_costs_mutate 'create_expense': creates the expense and links it to the job, CAS on both
-- revisions, idempotent requestId) and stores the metadata in the SAME transaction exactly as the
-- expense metadata writer does (pro_expense_billing). Nothing else changes.
begin;
create or replace function public.pro_work_cost_expense_create(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare meta_keys text[]:=array['billable','paymentMethod','vatRateBps','category'];result jsonb;eid uuid;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'create_expense' then raise exception 'Invalid cost' using errcode='22023';end if;
 if (p_input ? 'billable' and jsonb_typeof(p_input->'billable') is distinct from 'boolean')
  or (p_input ? 'paymentMethod' and (jsonb_typeof(p_input->'paymentMethod') not in('string','null') or p_input->>'paymentMethod' not in('cash','transfer','card','sinpe','check','other')))
  or (p_input ? 'vatRateBps' and (jsonb_typeof(p_input->'vatRateBps') not in('number','null') or (p_input->>'vatRateBps')::integer not in(50,100,200,400,1300)))
  or (p_input ? 'category' and (jsonb_typeof(p_input->'category') not in('string','null') or p_input->>'category' not in('materials','labor','subcontract','equipment','transport','permits','other'))) then
  raise exception 'Invalid cost metadata' using errcode='22023';end if;
 result:=public.pro_work_costs_mutate(p_user,p_input-meta_keys);
 eid:=(p_input->>'expenseId')::uuid;
 if p_input ?| meta_keys and exists(select 1 from public.pro_internal_expenses where user_id=p_user and id=eid) then
  insert into public.pro_expense_billing(user_id,expense_id,billable,payment_method,vat_rate_bps,category)
  values(p_user,eid,coalesce((p_input->>'billable')::boolean,false),p_input->>'paymentMethod',(p_input->>'vatRateBps')::integer,p_input->>'category')
  on conflict(user_id,expense_id) do update set billable=excluded.billable,payment_method=excluded.payment_method,vat_rate_bps=excluded.vat_rate_bps,category=excluded.category,updated_at=now();
 end if;
 return result;
end $$;
revoke all on function public.pro_work_cost_expense_create(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_cost_expense_create(uuid,jsonb) to service_role;
commit;
notify pgrst,'reload schema';

-- ===== catalog-details-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): catalog item image and preferred vendor.
-- A side table keyed by the catalog item (pro_products) so the generic catalog writer and its rows
-- stay unchanged. The preferred vendor comes from the vendor directory (pro_expense_suppliers, the
-- same list as Proveedores). The image is a private JPEG normalized on the server (same pattern as
-- the company files: base64 body → sharp → private bucket <owner>/<image>.jpg, SHA-256 checked on
-- read); the size limit is the shared Pro file limit (see file-size-limits-local.sql).
-- Patterns: RLS, service_role-only, security invoker, CAS revision (40001), idempotent actionId,
-- immutable history.
begin;
create table if not exists public.pro_product_details(
 user_id uuid not null,product_id text not null,
 preferred_vendor_id uuid,
 image_id uuid,image_path text check(image_path is null or image_path~'^[a-f0-9-]{36}/[a-f0-9-]{36}\.jpg$'),
 image_sha256 text check(image_sha256 is null or image_sha256~'^[a-f0-9]{64}$'),image_size integer check(image_size is null or image_size between 1 and 20971520),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(user_id,product_id),
 foreign key(user_id,product_id) references public.pro_products(user_id,id) on delete cascade,
 foreign key(user_id,preferred_vendor_id) references public.pro_expense_suppliers(user_id,id) on delete set null (preferred_vendor_id),
 check((image_id is null)=(image_path is null) and (image_id is null)=(image_sha256 is null) and (image_id is null)=(image_size is null)),
 check(image_path is null or split_part(image_path,'/',1)=user_id::text and split_part(image_path,'/',2)=image_id::text||'.jpg'));
create table if not exists public.pro_product_detail_history(
 user_id uuid not null,product_id text not null,action_id uuid not null,action text not null check(action in('set_vendor','set_image','remove_image')),
 before_state jsonb,after_state jsonb not null,at timestamptz not null default now(),primary key(user_id,action_id));
create table if not exists public.pro_product_detail_actions(
 user_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default now(),primary key(user_id,action_id));

create or replace function public.pro_product_detail_json(p_user uuid,p_product text) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('productId',p_product,'revision',coalesce(d.revision,0),'vendorId',d.preferred_vendor_id,
  'vendorName',(select s.name from public.pro_expense_suppliers s where s.user_id=p_user and s.id=d.preferred_vendor_id),
  'imageId',d.image_id,'imageSize',d.image_size)
 from (select 1) one left join public.pro_product_details d on d.user_id=p_user and d.product_id=p_product
$$;
create or replace function public.pro_product_details_read(p_user uuid,p_products text[]) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_products is null or cardinality(p_products)>50 then raise exception 'Invalid products' using errcode='22023';end if;
 return coalesce((select jsonb_object_agg(p.id,public.pro_product_detail_json(p_user,p.id)) from public.pro_products p where p.user_id=p_user and p.id=any(p_products)),'{}'::jsonb);
end $$;
create or replace function public.pro_product_image_read(p_user uuid,p_product text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare d public.pro_product_details;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into d from public.pro_product_details where user_id=p_user and product_id=p_product and image_id is not null;
 if not found then return null;end if;
 return jsonb_build_object('objectPath',d.image_path,'sha256',d.image_sha256,'sizeBytes',d.image_size,'imageId',d.image_id);
end $$;
-- Returns {result, previousPath} so the route can delete a replaced image's bytes after commit.
create or replace function public.pro_product_details_mutate(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;pid text:=p_input->>'productId';keys text[];hash text:=md5(p_input::text);prior public.pro_product_detail_actions;d public.pro_product_details;before_state jsonb;answer jsonb;previous text;vendor uuid;img uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act='set_vendor' and keys is distinct from array['action','actionId','productId','revision','vendorId']
  or act='set_image' and keys is distinct from array['action','actionId','imageId','objectPath','productId','revision','sha256','sizeBytes']
  or act='remove_image' and keys is distinct from array['action','actionId','productId','revision']
  or act is null or act not in('set_vendor','set_image','remove_image') or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid catalog item details' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-product-details:'||p_user::text||':'||coalesce(pid,''),0));
 select * into prior from public.pro_product_detail_actions where user_id=p_user and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if not exists(select 1 from public.pro_products where user_id=p_user and id=pid) then raise exception 'Catalog item unavailable' using errcode='P0002';end if;
 select * into d from public.pro_product_details where user_id=p_user and product_id=pid for update;
 if coalesce(d.revision,0)<>(p_input->>'revision')::integer then raise exception 'Catalog item changed' using errcode='40001';end if;
 before_state:=public.pro_product_detail_json(p_user,pid);
 if act='set_vendor' then
  begin vendor:=nullif(p_input->>'vendorId','')::uuid;exception when others then raise exception 'Invalid vendor' using errcode='22023';end;
  if vendor is not null and not exists(select 1 from public.pro_expense_suppliers where user_id=p_user and id=vendor and not coalesce(archived,false)) then raise exception 'Vendor unavailable' using errcode='22023';end if;
  insert into public.pro_product_details(user_id,product_id,preferred_vendor_id) values(p_user,pid,vendor)
  on conflict(user_id,product_id) do update set preferred_vendor_id=excluded.preferred_vendor_id,revision=public.pro_product_details.revision+1,updated_at=now();
 elsif act='set_image' then
  begin img:=(p_input->>'imageId')::uuid;exception when others then raise exception 'Invalid image' using errcode='22023';end;
  if p_input->>'objectPath'<>p_user::text||'/'||img::text||'.jpg' or coalesce(p_input->>'sha256','')!~'^[a-f0-9]{64}$' or jsonb_typeof(p_input->'sizeBytes')<>'number' or (p_input->>'sizeBytes')::integer not between 1 and 20971520 then raise exception 'Invalid image' using errcode='22023';end if;
  previous:=d.image_path;
  insert into public.pro_product_details(user_id,product_id,image_id,image_path,image_sha256,image_size) values(p_user,pid,img,p_input->>'objectPath',p_input->>'sha256',(p_input->>'sizeBytes')::integer)
  on conflict(user_id,product_id) do update set image_id=excluded.image_id,image_path=excluded.image_path,image_sha256=excluded.image_sha256,image_size=excluded.image_size,revision=public.pro_product_details.revision+1,updated_at=now();
 else
  if d.image_id is null then raise exception 'No image' using errcode='22023';end if;previous:=d.image_path;
  update public.pro_product_details set image_id=null,image_path=null,image_sha256=null,image_size=null,revision=revision+1,updated_at=now() where user_id=p_user and product_id=pid;
 end if;
 answer:=jsonb_build_object('detail',public.pro_product_detail_json(p_user,pid),'previousPath',previous);
 insert into public.pro_product_detail_history(user_id,product_id,action_id,action,before_state,after_state) values(p_user,pid,aid,act,before_state,answer->'detail');
 insert into public.pro_product_detail_actions(user_id,action_id,input_hash,result) values(p_user,aid,hash,answer);
 return answer;
end $$;
create or replace function public.pro_product_details_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Immutable catalog item history' using errcode='23514';end $$;

do $$declare t text;f record;begin
 foreach t in array array['pro_product_details','pro_product_detail_history','pro_product_detail_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_product_detail_history','pro_product_detail_actions'] loop
  execute format('drop trigger if exists pro_product_details_immutable on public.%I',t);execute format('create trigger pro_product_details_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_product_details_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_product_detail_json','pro_product_details_read','pro_product_image_read','pro_product_details_mutate','pro_product_details_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-catalog-images','pro-catalog-images',false,20971520,array['image/jpeg']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-catalog-images' and not public and file_size_limit=20971520 and allowed_mime_types=array['image/jpeg']) then raise exception 'Catalog image bucket is not private JPEG 20 MiB';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== file-size-limits-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): one file size limit for the private Pro files.
-- The six modules with private uploads (work files, daily log files, company files, task
-- discussion files, expense receipts, bid portal files) move from 3 MiB (2 MiB for normalized
-- JPEG) to the global cap of the local storage stack: 20 MiB (supabase/config.toml
-- file_size_limit = "20MiB", which this module does NOT change). Production target is 25 MB and
-- needs the storage global limit raised by the owner first. Each module's writer, fresh table check
-- and bucket were updated in place (its bucket insert now updates the limit on reapply); this module
-- migrates the existing table CHECK constraints (no rows touched: every stored size already fits)
-- and verifies tables + buckets. Delivery photos (pro_work_delivery_photos, 2 MiB) are not part of it.
begin;
do $$declare r record;tables regclass[]:=array['public.pro_work_files','public.pro_daily_log_files','public.pro_company_files','public.pro_team_task_files','public.pro_expense_receipts','public.pro_bid_portal_files']::regclass[];def text;
begin
 for r in select c.conrelid::regclass rel,c.conname,pg_get_constraintdef(c.oid) d from pg_constraint c where c.conrelid=any(tables) and c.contype='c' and pg_get_constraintdef(c.oid)~'\m(3145728|2097152)\M' loop
  def:=regexp_replace(r.d,'\m(3145728|2097152)\M','20971520','g');
  execute format('alter table %s drop constraint %I',r.rel,r.conname);
  execute format('alter table %s add constraint %I %s',r.rel,r.conname,def);
 end loop;
 if exists(select 1 from pg_constraint c where c.conrelid=any(tables) and pg_get_constraintdef(c.oid)~'\m(3145728|2097152)\M') then raise exception 'A Pro file table still limits files to 3 MiB';end if;
 if (select count(*) from pg_constraint c where c.conrelid=any(tables) and c.contype='c' and pg_get_constraintdef(c.oid)~'\m20971520\M')<6 then raise exception 'Pro file tables are missing the 20 MiB check';end if;
 if to_regclass('storage.buckets') is not null then
  update storage.buckets set file_size_limit=20971520 where id in('pro-work-files','pro-daily-log-files','pro-company-files','pro-team-task-files','pro-expense-receipts','pro-bid-portal-files') and file_size_limit is distinct from 20971520;
  if exists(select 1 from storage.buckets where id in('pro-work-files','pro-daily-log-files','pro-company-files','pro-team-task-files','pro-expense-receipts','pro-bid-portal-files') and (public or file_size_limit is distinct from 20971520)) then raise exception 'Pro file buckets are not private with 20 MiB';end if;
 end if;
end $$;
commit;

-- ===== work-messages-local.sql =====
-- LOCAL PRO ONLY. Round 7C (2026-11-13): «Mensajes» between the professional and the customer of a
-- job. One thread per linked customer request (pro_appointment_requests with a customer account and a
-- job, confirmed or completed; also invitation links). The side of the author is derived on the
-- server: the request owner writes as 'pro', the linked customer account as 'client'; anyone else
-- gets 42501. Messages are immutable (no edit/delete), idempotent by actionId, and nothing is sent
-- outside ContrataCR (no email, SMS, WhatsApp or push): the other side sees them in the app with an
-- unread count (read marker per side). Patterns: RLS, service_role-only, security invoker.
begin;
create table if not exists public.pro_work_messages(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,work_id text not null,request_id uuid not null,
 side text not null check(side in('pro','client')),author_id uuid not null,author_name text not null default '' check(length(author_name)<=160),
 body text not null check(length(body) between 1 and 2000 and body=btrim(body)),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id));
create index if not exists pro_work_messages_thread_idx on public.pro_work_messages(request_id,created_at desc,id desc);
create index if not exists pro_work_messages_work_idx on public.pro_work_messages(owner_id,work_id,created_at desc);
create table if not exists public.pro_work_message_reads(
 request_id uuid not null,side text not null check(side in('pro','client')),last_read_at timestamptz not null,
 primary key(request_id,side));
create table if not exists public.pro_work_message_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default now(),
 primary key(actor_id,action_id));

-- Side of p_actor in the thread of p_request (null when neither the owner nor the linked customer).
create or replace function public.pro_work_message_side(p_actor uuid,p_request uuid) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when r.owner_id=p_actor and coalesce(public.pro_private_work_tools_enabled(p_actor),false) then 'pro'
  when r.client_user_id=p_actor then 'client' end
 from public.pro_appointment_requests r join public.profiles p on p.id=p_actor and not coalesce(p.is_disabled,false)
 where r.id=p_request and r.work_id is not null and r.client_user_id is not null and r.status in('confirmed','completed')
$$;
create or replace function public.pro_work_message_json(m public.pro_work_messages) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',m.id,'side',m.side,'authorName',m.author_name,'body',m.body,'createdAt',m.created_at)
$$;
create or replace function public.pro_work_message_unread(p_request uuid,p_side text) returns integer language sql stable security invoker set search_path=public,pg_temp as $$
 select count(*)::integer from public.pro_work_messages m where m.request_id=p_request and m.side<>p_side
  and m.created_at>coalesce((select last_read_at from public.pro_work_message_reads where request_id=p_request and side=p_side),'-infinity'::timestamptz)
$$;

-- Thread page (newest 30 before the cursor, returned oldest→newest) + unread count of the reader.
create or replace function public.pro_work_messages_read(p_actor uuid,p_request uuid,p_before uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare me text:=public.pro_work_message_side(p_actor,p_request);anchor public.pro_work_messages;items jsonb;more boolean;r public.pro_appointment_requests;
begin
 if me is null then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_appointment_requests where id=p_request;
 if p_before is not null then select * into anchor from public.pro_work_messages where request_id=p_request and id=p_before;if not found then raise exception 'Cursor changed' using errcode='40001';end if;end if;
 with page as(select * from public.pro_work_messages m where m.request_id=p_request and(p_before is null or (m.created_at,m.id)<(anchor.created_at,anchor.id)) order by m.created_at desc,m.id desc limit 31)
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'side',p.side,'authorName',p.author_name,'body',p.body,'createdAt',p.created_at) order by p.created_at,p.id) filter(where rn<=30),'[]'::jsonb),count(*)>30 into items,more from (select page.*,row_number() over(order by created_at desc,id desc) rn from page) p;
 return jsonb_build_object('requestId',p_request,'workId',r.work_id,'side',me,'items',items,'hasMore',more,'unread',public.pro_work_message_unread(p_request,me),
  'counterpart',case when me='pro' then coalesce(nullif(btrim(r.client_name),''),'Cliente') else coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=r.owner_id),public.pro_team_name(r.owner_id)) end);
end $$;

-- Owner: threads of one job (customer requests linked to it) with unread counts.
create or replace function public.pro_work_message_threads(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('workId',p_work,'threads',coalesce((select jsonb_agg(jsonb_build_object('requestId',r.id,'clientName',coalesce(nullif(btrim(r.client_name),''),'Cliente'),'unread',public.pro_work_message_unread(r.id,'pro'),
   'lastAt',(select max(created_at) from public.pro_work_messages m where m.request_id=r.id)) order by r.created_at)
  from public.pro_appointment_requests r where r.owner_id=p_actor and r.work_id=p_work and r.client_user_id is not null and r.status in('confirmed','completed')),'[]'::jsonb));
end $$;

create or replace function public.pro_work_messages_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;rid uuid;me text;keys text[];hash text:=md5(p_input::text);prior public.pro_work_message_actions;r public.pro_appointment_requests;m public.pro_work_messages;body_text text;answer jsonb;
begin
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act='post' and keys is distinct from array['action','actionId','body','requestId'] or act='read' and keys is distinct from array['action','requestId'] or act is null or act not in('post','read') then raise exception 'Invalid message' using errcode='22023';end if;
 begin rid:=(p_input->>'requestId')::uuid;if act='post' then aid:=(p_input->>'actionId')::uuid;end if;exception when others then raise exception 'Invalid message' using errcode='22023';end;
 me:=public.pro_work_message_side(p_actor,rid);if me is null then raise exception 'Forbidden' using errcode='42501';end if;
 if act='read' then
  insert into public.pro_work_message_reads(request_id,side,last_read_at) values(rid,me,clock_timestamp()) on conflict(request_id,side) do update set last_read_at=greatest(public.pro_work_message_reads.last_read_at,excluded.last_read_at);
  return jsonb_build_object('requestId',rid,'unread',0);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-message:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_work_message_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 body_text:=btrim(coalesce(p_input->>'body',''));
 if jsonb_typeof(p_input->'body') is distinct from 'string' or length(body_text) not between 1 and 2000 then raise exception 'Invalid message body' using errcode='22023';end if;
 if (select count(*) from public.pro_work_messages where request_id=rid and author_id=p_actor and created_at>clock_timestamp()-interval '1 minute')>=20 then raise exception 'Too many messages' using errcode='54000';end if;
 select * into r from public.pro_appointment_requests where id=rid;
 insert into public.pro_work_messages(owner_id,id,work_id,request_id,side,author_id,author_name,body) values(r.owner_id,aid,r.work_id,rid,me,p_actor,left(coalesce(case when me='pro' then (select nullif(btrim(business_name),'') from public.professionals where profile_id=r.owner_id) end,public.pro_team_name(p_actor),''),160),body_text) returning * into m;
 -- Writing marks the thread as read for the author.
 insert into public.pro_work_message_reads(request_id,side,last_read_at) values(rid,me,m.created_at) on conflict(request_id,side) do update set last_read_at=greatest(public.pro_work_message_reads.last_read_at,excluded.last_read_at);
 answer:=jsonb_build_object('message',public.pro_work_message_json(m));
 insert into public.pro_work_message_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;
create or replace function public.pro_work_messages_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Messages are immutable' using errcode='23514';end $$;

do $$declare t text;f record;begin
 foreach t in array array['pro_work_messages','pro_work_message_reads','pro_work_message_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_work_messages','pro_work_message_actions'] loop
  execute format('drop trigger if exists pro_work_messages_immutable on public.%I',t);execute format('create trigger pro_work_messages_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_work_messages_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_work_message_side','pro_work_message_json','pro_work_message_unread','pro_work_messages_read','pro_work_message_threads','pro_work_messages_mutate','pro_work_messages_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== subcontractor-access-local.sql =====
-- LOCAL PRO ONLY. Round 8 (2026-11-15): subcontractor access with a limited scope.
-- The owner invites a vendor of the directory (pro_expense_suppliers + kind) by e-mail: the server
-- keeps only the SHA-256 of a one-use code (72 h); nothing is sent (the owner copies the code). A
-- registered account whose verified e-mail matches accepts it. The access is then linked to specific
-- jobs; on each job the owner assigns tasks and shares job files with it.
-- The subcontractor sees ONLY, per linked job: the job service, the customer's name, the job dates,
-- the planned dates of ITS assigned tasks and the key dates (schedule), its assigned tasks (comment,
-- mark done / reopen with CAS) and the files shared with it. Never finances, contact data, other
-- tasks, notes, messages, other jobs or other companies. Everything is enforced here (security
-- invoker functions called with service_role only); the API routes only pass the real identity.
-- Patterns: RLS on, service_role-only, idempotent actionId, CAS 40001, immutable events/comments.
begin;
create table if not exists public.pro_subcontractor_access(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 supplier_id uuid not null,vendor_name text not null check(length(btrim(vendor_name)) between 1 and 160),
 recipient_email text not null check(length(recipient_email) between 3 and 254 and recipient_email=lower(btrim(recipient_email))),
 token_sha256 text not null unique check(token_sha256~'^[a-f0-9]{64}$'),
 status text not null default 'pending' check(status in('pending','active','revoked')),
 -- Captured identity of the accepting account (no profile FK: deleting that account must not block the owner's history).
 member_user_id uuid,member_name text not null default '' check(length(member_name)<=160),
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,accepted_at timestamptz,revoked_at timestamptz,
 primary key(owner_id,id),
 foreign key(owner_id,supplier_id) references public.pro_expense_suppliers(user_id,id) on delete cascade,
 check(status<>'active' or member_user_id is not null));
create unique index if not exists pro_subcontractor_access_member on public.pro_subcontractor_access(owner_id,member_user_id) where status='active';
create index if not exists pro_subcontractor_access_member_page on public.pro_subcontractor_access(member_user_id) where status='active';
create table if not exists public.pro_subcontractor_jobs(
 owner_id uuid not null,access_id uuid not null,work_id text not null,active boolean not null default true,
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,access_id,work_id),
 foreign key(owner_id,access_id) references public.pro_subcontractor_access(owner_id,id) on delete cascade,
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade);
create index if not exists pro_subcontractor_jobs_work on public.pro_subcontractor_jobs(owner_id,work_id) where active;
create table if not exists public.pro_subcontractor_tasks(
 owner_id uuid not null,access_id uuid not null,work_id text not null,task_id uuid not null,active boolean not null default true,
 updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,access_id,task_id),
 foreign key(owner_id,access_id,work_id) references public.pro_subcontractor_jobs(owner_id,access_id,work_id) on delete cascade,
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_subcontractor_files(
 owner_id uuid not null,access_id uuid not null,work_id text not null,file_id uuid not null,active boolean not null default true,
 updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,access_id,file_id),
 foreign key(owner_id,access_id,work_id) references public.pro_subcontractor_jobs(owner_id,access_id,work_id) on delete cascade,
 foreign key(owner_id,work_id,file_id) references public.pro_work_files(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_subcontractor_comments(
 owner_id uuid not null,id uuid not null,access_id uuid not null,work_id text not null,task_id uuid not null,
 side text not null check(side in('pro','sub')),author_id uuid not null,author_name text not null default '' check(length(author_name)<=160),
 body text not null check(length(body) between 1 and 1000 and body=btrim(body)),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade);
create index if not exists pro_subcontractor_comments_task on public.pro_subcontractor_comments(owner_id,access_id,task_id,created_at,id);
create table if not exists public.pro_subcontractor_events(
 owner_id uuid not null,id uuid not null default gen_random_uuid(),access_id uuid not null,actor_id uuid not null,
 action text not null check(action in('invite','accept','add_job','remove_job','assign_task','unassign_task','share_file','unshare_file','revoke','comment','complete','reopen')),
 work_id text,subject_id text,at timestamptz not null default clock_timestamp(),primary key(owner_id,id));
create index if not exists pro_subcontractor_events_page on public.pro_subcontractor_events(owner_id,access_id,at desc);
create table if not exists public.pro_subcontractor_actions(
 actor_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(actor_id,action_id));

create or replace function public.pro_sub_access_json(a public.pro_subcontractor_access) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',a.id,'supplierId',a.supplier_id,'vendorName',a.vendor_name,'email',a.recipient_email,'status',
  case when a.status='pending' and a.expires_at<=clock_timestamp() then 'expired' else a.status end,
  'memberName',nullif(a.member_name,''),'revision',a.revision,'createdAt',a.created_at,'expiresAt',a.expires_at,'acceptedAt',a.accepted_at)
$$;

-- Owner view of one job: accesses linked to it (with assigned tasks / shared files) and the others that can be added.
create or replace function public.pro_sub_owner_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 return jsonb_build_object('workId',p_work,
  'linked',coalesce((select jsonb_agg(public.pro_sub_access_json(a)||jsonb_build_object(
     'taskIds',coalesce((select jsonb_agg(t.task_id) from public.pro_subcontractor_tasks t where t.owner_id=a.owner_id and t.access_id=a.id and t.work_id=p_work and t.active),'[]'::jsonb),
     'fileIds',coalesce((select jsonb_agg(f.file_id) from public.pro_subcontractor_files f where f.owner_id=a.owner_id and f.access_id=a.id and f.work_id=p_work and f.active),'[]'::jsonb),
     'comments',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'taskId',c.task_id,'side',c.side,'authorName',c.author_name,'body',c.body,'createdAt',c.created_at) order by c.created_at,c.id)
       from public.pro_subcontractor_comments c where c.owner_id=a.owner_id and c.access_id=a.id and c.work_id=p_work),'[]'::jsonb)) order by a.vendor_name,a.id)
   from public.pro_subcontractor_access a join public.pro_subcontractor_jobs j on j.owner_id=a.owner_id and j.access_id=a.id and j.work_id=p_work and j.active
   where a.owner_id=p_actor and a.status<>'revoked'),'[]'::jsonb),
  'available',coalesce((select jsonb_agg(public.pro_sub_access_json(a) order by a.vendor_name,a.id) from public.pro_subcontractor_access a
   where a.owner_id=p_actor and a.status<>'revoked' and not exists(select 1 from public.pro_subcontractor_jobs j where j.owner_id=a.owner_id and j.access_id=a.id and j.work_id=p_work and j.active)),'[]'::jsonb),
  'vendors',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'kind',coalesce(p.kind,'supplier'),'trade',p.trade) order by (coalesce(p.kind,'supplier')<>'subcontractor'),s.name,s.id)
   from public.pro_expense_suppliers s left join public.pro_company_vendor_profiles p on p.owner_id=s.user_id and p.supplier_id=s.id where s.user_id=p_actor),'[]'::jsonb),
  'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'status',t.status,'dueDate',t.due_date) order by t.created_at,t.id)
   from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=p_work and not t.archived),'[]'::jsonb),
  'files',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'name',f.name,'mimeType',f.mime_type) order by f.created_at desc,f.id)
   from public.pro_work_files f where f.owner_id=p_actor and f.work_id=p_work and f.ready),'[]'::jsonb));
end $$;

create or replace function public.pro_sub_owner_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;acc uuid;wid text;subject uuid;keys text[];hash text:=md5(p_input::text);prior public.pro_subcontractor_actions;
 a public.pro_subcontractor_access;sup record;email text;answer jsonb;on_flag boolean;rev integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid subcontractor action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act is null or not(
   act='invite' and keys=array['action','actionId','email','supplierId','tokenSha256','workId']
   or act in('add_job','remove_job') and keys=array['accessId','action','actionId','workId']
   or act in('assign_task','share_file') and keys=array['accessId','action','actionId','on','subjectId','workId']
   or act='revoke' and keys=array['accessId','action','actionId','revision']
   or act='comment' and keys=array['accessId','action','actionId','body','subjectId','workId']) then raise exception 'Invalid subcontractor action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;acc:=nullif(p_input->>'accessId','')::uuid;subject:=nullif(p_input->>'subjectId','')::uuid;
  exception when others then raise exception 'Invalid subcontractor action' using errcode='22023';end;
 wid:=p_input->>'workId';
 perform pg_advisory_xact_lock(hashtextextended('pro-sub:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_subcontractor_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if wid is not null and not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 if act='invite' then
  email:=lower(btrim(coalesce(p_input->>'email','')));
  if email!~'^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(email)>254 or coalesce(p_input->>'tokenSha256','')!~'^[a-f0-9]{64}$' then raise exception 'Invalid subcontractor invite' using errcode='22023';end if;
  begin select s.id,s.name into sup from public.pro_expense_suppliers s where s.user_id=p_actor and s.id=(p_input->>'supplierId')::uuid;exception when others then raise exception 'Invalid subcontractor invite' using errcode='22023';end;
  if sup.id is null then raise exception 'Forbidden' using errcode='42501';end if;
  if (select count(*) from public.pro_subcontractor_access where owner_id=p_actor and created_at>clock_timestamp()-interval '1 hour')>=30 then raise exception 'Too many invites' using errcode='54000';end if;
  insert into public.pro_subcontractor_access(owner_id,id,supplier_id,vendor_name,recipient_email,token_sha256,expires_at)
   values(p_actor,aid,sup.id,left(btrim(sup.name),160),email,p_input->>'tokenSha256',clock_timestamp()+interval '72 hours') returning * into a;
  insert into public.pro_subcontractor_jobs(owner_id,access_id,work_id) values(p_actor,a.id,wid);
  insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id) values(p_actor,a.id,p_actor,'invite',wid);
  answer:=jsonb_build_object('action',act,'access',public.pro_sub_access_json(a));
 else
  select * into a from public.pro_subcontractor_access where owner_id=p_actor and id=acc for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if a.status='revoked' then raise exception 'Access revoked' using errcode='22023';end if;
  if act='revoke' then
   begin rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid subcontractor action' using errcode='22023';end;
   if rev<>a.revision then raise exception 'Access changed' using errcode='40001';end if;
   update public.pro_subcontractor_access set status='revoked',revoked_at=clock_timestamp(),revision=revision+1 where owner_id=p_actor and id=acc returning * into a;
   update public.pro_subcontractor_jobs set active=false,updated_at=clock_timestamp() where owner_id=p_actor and access_id=acc and active;
   insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action) values(p_actor,acc,p_actor,'revoke');
  elsif act='add_job' then
   insert into public.pro_subcontractor_jobs(owner_id,access_id,work_id) values(p_actor,acc,wid) on conflict(owner_id,access_id,work_id) do update set active=true,updated_at=clock_timestamp();
   insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id) values(p_actor,acc,p_actor,'add_job',wid);
  elsif act='remove_job' then
   -- Assignments and shares stay recorded but stop applying while the job is not linked.
   update public.pro_subcontractor_jobs set active=false,updated_at=clock_timestamp() where owner_id=p_actor and access_id=acc and work_id=wid;
   insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id) values(p_actor,acc,p_actor,'remove_job',wid);
  else
   if not exists(select 1 from public.pro_subcontractor_jobs where owner_id=p_actor and access_id=acc and work_id=wid and active) then raise exception 'Job not linked' using errcode='42501';end if;
   if act='comment' then
    if a.status<>'active' then raise exception 'Access not active' using errcode='22023';end if;
    if not exists(select 1 from public.pro_subcontractor_tasks where owner_id=p_actor and access_id=acc and task_id=subject and work_id=wid and active) then raise exception 'Forbidden' using errcode='42501';end if;
    if jsonb_typeof(p_input->'body') is distinct from 'string' or length(btrim(p_input->>'body')) not between 1 and 1000 then raise exception 'Invalid comment' using errcode='22023';end if;
    insert into public.pro_subcontractor_comments(owner_id,id,access_id,work_id,task_id,side,author_id,author_name,body)
     values(p_actor,aid,acc,wid,subject,'pro',p_actor,left(coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=p_actor),public.pro_team_name(p_actor)),160),btrim(p_input->>'body'));
    insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id,subject_id) values(p_actor,acc,p_actor,'comment',wid,subject::text);
   else
    if jsonb_typeof(p_input->'on') is distinct from 'boolean' then raise exception 'Invalid subcontractor action' using errcode='22023';end if;
    on_flag:=(p_input->>'on')::boolean;
    if act='assign_task' then
     if not exists(select 1 from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=subject and not archived) then raise exception 'Forbidden' using errcode='42501';end if;
     insert into public.pro_subcontractor_tasks(owner_id,access_id,work_id,task_id,active) values(p_actor,acc,wid,subject,on_flag) on conflict(owner_id,access_id,task_id) do update set active=excluded.active,updated_at=clock_timestamp();
     insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id,subject_id) values(p_actor,acc,p_actor,case when on_flag then 'assign_task' else 'unassign_task' end,wid,subject::text);
    else
     if not exists(select 1 from public.pro_work_files where owner_id=p_actor and work_id=wid and id=subject and ready) then raise exception 'Forbidden' using errcode='42501';end if;
     insert into public.pro_subcontractor_files(owner_id,access_id,work_id,file_id,active) values(p_actor,acc,wid,subject,on_flag) on conflict(owner_id,access_id,file_id) do update set active=excluded.active,updated_at=clock_timestamp();
     insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id,subject_id) values(p_actor,acc,p_actor,case when on_flag then 'share_file' else 'unshare_file' end,wid,subject::text);
    end if;
   end if;
  end if;
  answer:=jsonb_build_object('action',act,'access',public.pro_sub_access_json(a));
 end if;
 insert into public.pro_subcontractor_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- The invited account accepts with its verified e-mail and the code hash.
create or replace function public.pro_sub_accept(p_actor uuid,p_verified_email text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;hash text:=md5(p_input::text);prior public.pro_subcontractor_actions;a public.pro_subcontractor_access;keys text[];answer jsonb;
begin
 if p_actor is null or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['actionId','tokenSha256'] or coalesce(p_input->>'tokenSha256','')!~'^[a-f0-9]{64}$' then raise exception 'Invalid code' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid code' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-sub:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_subcontractor_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into a from public.pro_subcontractor_access where token_sha256=p_input->>'tokenSha256' for update;
 if not found or a.status<>'pending' or a.expires_at<=clock_timestamp() then raise exception 'Code not available' using errcode='P0002';end if;
 if a.owner_id=p_actor then raise exception 'Forbidden' using errcode='42501';end if;
 if p_verified_email is null or lower(btrim(p_verified_email))<>a.recipient_email then raise exception 'Forbidden' using errcode='42501';end if;
 if exists(select 1 from public.pro_subcontractor_access where owner_id=a.owner_id and member_user_id=p_actor and status='active') then raise exception 'Already linked' using errcode='23505';end if;
 update public.pro_subcontractor_access set status='active',member_user_id=p_actor,member_name=left(public.pro_team_name(p_actor),160),accepted_at=clock_timestamp(),revision=revision+1
  where owner_id=a.owner_id and id=a.id returning * into a;
 insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action) values(a.owner_id,a.id,p_actor,'accept');
 answer:=jsonb_build_object('action','accept','ownerName',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=a.owner_id),public.pro_team_name(a.owner_id)));
 insert into public.pro_subcontractor_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- Subcontractor portal: only its linked jobs (every company), projected.
create or replace function public.pro_sub_portal_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if p_actor is null or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('jobs',coalesce((select jsonb_agg(jsonb_build_object(
   'ownerId',a.owner_id,'accessId',a.id,'workId',w.id,
   'company',coalesce((select nullif(btrim(business_name),'') from public.professionals where profile_id=a.owner_id),public.pro_team_name(a.owner_id)),
   'service',w.service,'customerName',coalesce(nullif(btrim(w.client),''),''),'start',nullif(w.start,''),'end',nullif(w."end",''),'cancelled',coalesce(w.cancelled,false),
   'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'details',t.details,'status',t.status,'dueDate',t.due_date,'revision',t.revision,
       'plannedStart',p.planned_start,'plannedEnd',p.planned_end,
       'comments',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'side',c.side,'authorName',c.author_name,'body',c.body,'createdAt',c.created_at) order by c.created_at,c.id)
         from public.pro_subcontractor_comments c where c.owner_id=a.owner_id and c.access_id=a.id and c.task_id=t.id),'[]'::jsonb)) order by coalesce(p.planned_start,t.due_date),t.created_at,t.id)
     from public.pro_subcontractor_tasks st join public.pro_work_tasks t on t.owner_id=st.owner_id and t.work_id=st.work_id and t.id=st.task_id and not t.archived
     left join public.pro_work_schedule_plans p on p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id
     where st.owner_id=a.owner_id and st.access_id=a.id and st.work_id=w.id and st.active),'[]'::jsonb),
   'keyDates',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'date',m.milestone_date) order by m.milestone_date,m.id)
     from public.pro_work_schedule_milestones m where m.owner_id=a.owner_id and m.work_id=w.id and not m.archived),'[]'::jsonb),
   'files',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes) order by f.created_at desc,f.id)
     from public.pro_subcontractor_files sf join public.pro_work_files f on f.owner_id=sf.owner_id and f.work_id=sf.work_id and f.id=sf.file_id and f.ready
     where sf.owner_id=a.owner_id and sf.access_id=a.id and sf.work_id=w.id and sf.active),'[]'::jsonb)) order by w.service,w.id)
  from public.pro_subcontractor_access a join public.pro_subcontractor_jobs j on j.owner_id=a.owner_id and j.access_id=a.id and j.active
  join public.pro_work w on w.user_id=j.owner_id and w.id=j.work_id
  where a.member_user_id=p_actor and a.status='active' and coalesce(public.pro_private_work_tools_enabled(a.owner_id),false)),'[]'::jsonb));
end $$;

-- Subcontractor writes: comment on / complete / reopen ITS assigned tasks.
create or replace function public.pro_sub_portal_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;acc uuid;tid uuid;own uuid;keys text[];hash text:=md5(p_input::text);prior public.pro_subcontractor_actions;
 a public.pro_subcontractor_access;t public.pro_work_tasks;answer jsonb;rev integer;full_before jsonb;
begin
 if p_actor is null or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act is null or not(act='comment' and keys=array['accessId','action','actionId','body','ownerId','taskId'] or act in('complete','reopen') and keys=array['accessId','action','actionId','ownerId','revision','taskId']) then raise exception 'Invalid action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;acc:=(p_input->>'accessId')::uuid;tid:=(p_input->>'taskId')::uuid;own:=(p_input->>'ownerId')::uuid;exception when others then raise exception 'Invalid action' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-sub:'||p_actor::text||':'||aid::text,0));
 select * into prior from public.pro_subcontractor_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into a from public.pro_subcontractor_access where owner_id=own and id=acc and member_user_id=p_actor and status='active';
 if not found or not coalesce(public.pro_private_work_tools_enabled(own),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select t2.* into t from public.pro_subcontractor_tasks st join public.pro_subcontractor_jobs j on j.owner_id=st.owner_id and j.access_id=st.access_id and j.work_id=st.work_id and j.active
  join public.pro_work_tasks t2 on t2.owner_id=st.owner_id and t2.work_id=st.work_id and t2.id=st.task_id and not t2.archived
  where st.owner_id=own and st.access_id=acc and st.task_id=tid and st.active for update of t2;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if act='comment' then
  if jsonb_typeof(p_input->'body') is distinct from 'string' or length(btrim(p_input->>'body')) not between 1 and 1000 then raise exception 'Invalid comment' using errcode='22023';end if;
  if (select count(*) from public.pro_subcontractor_comments where author_id=p_actor and created_at>clock_timestamp()-interval '1 minute')>=20 then raise exception 'Too many comments' using errcode='54000';end if;
  insert into public.pro_subcontractor_comments(owner_id,id,access_id,work_id,task_id,side,author_id,author_name,body) values(own,aid,acc,t.work_id,tid,'sub',p_actor,left(coalesce(nullif(a.member_name,''),a.vendor_name),160),btrim(p_input->>'body'));
  insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id,subject_id) values(own,acc,p_actor,'comment',t.work_id,tid::text);
  answer:=jsonb_build_object('action',act,'taskId',tid);
 else
  begin rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid action' using errcode='22023';end;
  if rev<>t.revision then raise exception 'Task changed' using errcode='40001';end if;
  if act='complete' and t.status<>'open' or act='reopen' and t.status<>'done' then raise exception 'Invalid task transition' using errcode='22023';end if;
  full_before:=public.pro_work_task_json(t);
  update public.pro_work_tasks set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=own and work_id=t.work_id and id=tid returning * into t;
  -- owner_id is storage scope; the real actor is recorded in pro_subcontractor_events/actions.
  insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(own,t.work_id,tid,aid,act,full_before,public.pro_work_task_json(t));
  insert into public.pro_subcontractor_events(owner_id,access_id,actor_id,action,work_id,subject_id) values(own,acc,p_actor,act,t.work_id,tid::text);
  answer:=jsonb_build_object('action',act,'taskId',tid,'status',t.status,'revision',t.revision);
 end if;
 insert into public.pro_subcontractor_actions(actor_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

-- Download of a shared file (object path for the server; null when not shared with this account).
create or replace function public.pro_sub_file_download(p_actor uuid,p_owner uuid,p_file uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type)
 from public.pro_subcontractor_files sf
 join public.pro_subcontractor_access a on a.owner_id=sf.owner_id and a.id=sf.access_id and a.member_user_id=p_actor and a.status='active'
 join public.pro_subcontractor_jobs j on j.owner_id=sf.owner_id and j.access_id=sf.access_id and j.work_id=sf.work_id and j.active
 join public.pro_work_files f on f.owner_id=sf.owner_id and f.work_id=sf.work_id and f.id=sf.file_id and f.ready
 where sf.owner_id=p_owner and sf.file_id=p_file and sf.active and coalesce(public.pro_private_work_tools_enabled(p_owner),false)
 limit 1
$$;

create or replace function public.pro_subcontractor_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Subcontractor history is immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_subcontractor_access','pro_subcontractor_jobs','pro_subcontractor_tasks','pro_subcontractor_files','pro_subcontractor_comments','pro_subcontractor_events','pro_subcontractor_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_subcontractor_comments','pro_subcontractor_events','pro_subcontractor_actions'] loop
  execute format('drop trigger if exists pro_subcontractor_immutable on public.%I',t);execute format('create trigger pro_subcontractor_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_subcontractor_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_sub_access_json','pro_sub_owner_read','pro_sub_owner_mutate','pro_sub_accept','pro_sub_portal_read','pro_sub_portal_mutate','pro_sub_file_download','pro_subcontractor_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== job-page-local.sql =====
-- LOCAL PRO ONLY. Round 8 (2026-11-15): the job as its own page and an editable job overview.
-- 1) pro_work_sidebar_read: right column of the job page (status, location, customer, collaborators,
--    upcoming meetings and key dates, tags) in one read; owner (or a company member working as the
--    owner through the role gate) only.
-- 2) Overview layout per person: the owner, or each company member separately (p_person), keeps an
--    ordered list of widgets and the hidden ones. CAS by revision (40001), idempotent by actionId,
--    immutable history. «Restablecer» stores the default (history keeps the previous layout).
-- 3) pro_role_route_capability: saving one's own overview layout is a personal preference ('read'),
--    so a «Solo lectura» member may arrange their own overview; every other route keeps its class.
--    Subcontractor management (`subcontractors`) is team management.
-- Patterns: RLS on, service_role-only grants, security invoker, America/Costa_Rica dates.
begin;
create table if not exists public.pro_overview_layouts(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 person_id uuid not null,
 layout jsonb not null,
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id));
create table if not exists public.pro_overview_layout_history(
 owner_id uuid not null,person_id uuid not null,action_id uuid not null,action text not null check(action in('save','reset')),
 before_layout jsonb,after_layout jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,action_id));
create table if not exists public.pro_overview_layout_actions(
 owner_id uuid not null,person_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,action_id));

-- The fixed widget catalogue of the job overview (work-overview.tsx).
create or replace function public.pro_overview_widgets() returns text[] language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['client','next','schedule','finance','activity','open']::text[]
$$;
create or replace function public.pro_overview_default_layout() returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('order',to_jsonb(public.pro_overview_widgets()),'hidden','[]'::jsonb)
$$;
-- The person must be the owner or an active member of the owner's company.
create or replace function public.pro_overview_person_ok(p_owner uuid,p_person uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(public.pro_private_work_tools_enabled(p_owner),false) and p_person is not null and public.pro_role_of(p_person,p_owner) is not null
$$;
create or replace function public.pro_overview_layout_read(p_actor uuid,p_person uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare row public.pro_overview_layouts;
begin
 if not public.pro_overview_person_ok(p_actor,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into row from public.pro_overview_layouts where owner_id=p_actor and person_id=p_person;
 if not found then return jsonb_build_object('layout',public.pro_overview_default_layout(),'revision',0,'custom',false,'widgets',to_jsonb(public.pro_overview_widgets()));end if;
 return jsonb_build_object('layout',row.layout,'revision',row.revision,'custom',row.layout<>public.pro_overview_default_layout(),'widgets',to_jsonb(public.pro_overview_widgets()));
end $$;
create or replace function public.pro_overview_layout_save(p_actor uuid,p_person uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;rev integer;keys text[];hash text:=md5(p_input::text);prior public.pro_overview_layout_actions;
 cur public.pro_overview_layouts;before_value jsonb;next_layout jsonb;ord text[];hid text[];answer jsonb;w text[]:=public.pro_overview_widgets();
begin
 if not public.pro_overview_person_ok(p_actor,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid layout' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act='save' and keys is distinct from array['action','actionId','layout','revision'] or act='reset' and keys is distinct from array['action','actionId','revision'] or act is null or act not in('save','reset') then raise exception 'Invalid layout' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid layout' using errcode='22023';end;
 if aid is null or rev is null or rev<0 then raise exception 'Invalid layout' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-overview-layout:'||p_actor::text||':'||p_person::text,0));
 select * into prior from public.pro_overview_layout_actions where owner_id=p_actor and person_id=p_person and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into cur from public.pro_overview_layouts where owner_id=p_actor and person_id=p_person for update;
 if coalesce(cur.revision,0)<>rev then raise exception 'Layout changed' using errcode='40001';end if;
 before_value:=cur.layout;
 if act='reset' then next_layout:=public.pro_overview_default_layout();
 else
  if jsonb_typeof(p_input->'layout') is distinct from 'object' or (select array_agg(k order by k) from jsonb_object_keys(p_input->'layout') k) is distinct from array['hidden','order']
   or jsonb_typeof(p_input->'layout'->'order') is distinct from 'array' or jsonb_typeof(p_input->'layout'->'hidden') is distinct from 'array' then raise exception 'Invalid layout' using errcode='22023';end if;
  select array_agg(value order by n) into ord from jsonb_array_elements_text(p_input->'layout'->'order') with ordinality e(value,n);
  select coalesce(array_agg(value order by n),'{}') into hid from jsonb_array_elements_text(p_input->'layout'->'hidden') with ordinality e(value,n);
  -- order: every widget exactly once; hidden: a subset without duplicates; at least one widget stays visible.
  if ord is null or cardinality(ord)<>cardinality(w) or not(ord @> w and w @> ord) or (select count(distinct x) from unnest(ord) x)<>cardinality(w)
   or not(w @> hid) or (select count(distinct x) from unnest(hid) x)<>cardinality(hid) or cardinality(hid)>=cardinality(w) then raise exception 'Invalid layout' using errcode='22023';end if;
  next_layout:=jsonb_build_object('order',to_jsonb(ord),'hidden',to_jsonb((select coalesce(array_agg(x order by array_position(ord,x)),'{}') from unnest(hid) x)));
 end if;
 insert into public.pro_overview_layouts(owner_id,person_id,layout,revision,updated_at) values(p_actor,p_person,next_layout,1,clock_timestamp())
  on conflict(owner_id,person_id) do update set layout=excluded.layout,revision=public.pro_overview_layouts.revision+1,updated_at=clock_timestamp()
  returning * into cur;
 insert into public.pro_overview_layout_history(owner_id,person_id,action_id,action,before_layout,after_layout) values(p_actor,p_person,aid,act,before_value,next_layout);
 answer:=jsonb_build_object('layout',cur.layout,'revision',cur.revision,'custom',cur.layout<>public.pro_overview_default_layout(),'widgets',to_jsonb(w));
 insert into public.pro_overview_layout_actions(owner_id,person_id,action_id,input_hash,result) values(p_actor,p_person,aid,hash,answer);
 return answer;
end $$;

-- Right column of the job page.
create or replace function public.pro_work_sidebar_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;d public.pro_project_details;today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then return null;end if;
 select * into d from public.pro_project_details where owner_id=p_actor and work_id=p_work;
 return jsonb_build_object(
  'workId',w.id,
  'status',jsonb_build_object('stage',w.stage,'cancelled',coalesce(w.cancelled,false),'start',nullif(w.start,''),'end',nullif(w."end",''),
    'phase',(public.pro_work_header_facts(p_actor,p_work))->>'phase'),
  'location',jsonb_build_object('address',d.address,
    'visit',(select nullif(btrim(r.location_text),'') from public.pro_appointment_requests r where r.owner_id=p_actor and r.work_id=p_work and nullif(btrim(r.location_text),'') is not null order by r.created_at desc limit 1)),
  'customer',jsonb_build_object('name',coalesce(nullif(btrim(w.client),''),(select nullif(btrim(r.client_name),'') from public.pro_appointment_requests r where r.owner_id=p_actor and r.work_id=p_work order by r.created_at limit 1)),
    'linked',exists(select 1 from public.pro_appointment_requests r where r.owner_id=p_actor and r.work_id=p_work and r.client_user_id is not null and r.status in('confirmed','completed'))),
  'collaborators',coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'name',name,'role',role) order by ord,name) from (
     select 'job' kind,coalesce(nullif(btrim(g.member_name),''),public.pro_team_name(g.member_user_id)) name,g.role role,1 ord from public.pro_team_grants g where g.owner_id=p_actor and g.work_id=p_work and g.active
     union all
     select 'subcontractor',coalesce(nullif(btrim(s.member_name),''),s.vendor_name),'subcontractor',2 from public.pro_subcontractor_jobs j join public.pro_subcontractor_access s on s.owner_id=j.owner_id and s.id=j.access_id
      where j.owner_id=p_actor and j.work_id=p_work and j.active and s.status='active'
   ) c),'[]'::jsonb),
  'meetings',coalesce((select jsonb_agg(m order by m->>'at') from (
     select jsonb_build_object('kind','appointment','id',r.id,'title',r.service,'at',coalesce(r.proposed_start,r.requested_start),'status',r.status) m
      from public.pro_appointment_requests r where r.owner_id=p_actor and r.work_id=p_work and r.status in('requested','proposed','confirmed')
       and coalesce(r.proposed_start,r.requested_start)>=clock_timestamp()-interval '2 hours'
     union all
     select jsonb_build_object('kind','milestone','id',m.id,'title',m.title,'at',m.milestone_date::text,'status','planned')
      from public.pro_work_schedule_milestones m where m.owner_id=p_actor and m.work_id=p_work and not m.archived and m.milestone_date>=today
     order by 1 limit 6) x),'[]'::jsonb),
  'tags',coalesce((select jsonb_agg(t.name order by l.position,t.name) from public.pro_project_tag_links l join public.pro_project_tags t on t.owner_id=l.owner_id and t.id=l.tag_id where l.owner_id=p_actor and l.work_id=p_work),'[]'::jsonb),
  'code',d.code,'color',d.color);
end $$;

-- Route capability for the role gate (same as team-roles-local.sql, plus the Round 8 routes).
create or replace function public.pro_role_route_capability(p_method text,p_path text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare seg text:=split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1);
begin
 if upper(coalesce(p_method,'')) in('GET','HEAD','OPTIONS') then return 'read';end if;
 -- Round 8: one's own overview arrangement is a personal preference, not a change to company data.
 if seg='overview-layout' then return 'read';end if;
 if seg in('team','team-roles','subcontractors') then return 'team.manage';end if;
 if seg ~ '^(integrations|connectors|oauth|site|site-public|marketing|marketing-confirm|ads-tracking|social|social-content|promotions|invoice-document-settings|invoice-issuer|accounting|accounting-export|einvoice|einvoice-file)$' then return 'settings.write';end if;
 if seg ~ '^(invoice-|payment-|pay$|client-operations|client-balance|client-statement|client-finances|credits-retainers|work-billing|work-budget|work-costs|expenses|expense-receipts|purchase-order|online-payments)' then return 'finance.write';end if;
 if seg ~ '^(lead-|request-pipeline|request-followups|manual-lead-)' then return 'lead.write';end if;
 if seg ~ '^(private-estimate|quote|quotes|contract|esign|appointment-|reservations|bids|bid-portal-links|work-changes|selections|allowances|project-quote-context|visit-preparation|work-client-invitations|client-dashboard|client-pending|client-fiscal|request-quotes|direct-project|workspace|projects|work-header|identity-lookup)' then return 'sales.write';end if;
 if seg ~ '^(catalog|company-|service-packages|discount-presets|task-templates|schedule-templates|ai|ai-meetings)' then return 'company.write';end if;
 return 'work.write';
end $$;

create or replace function public.pro_overview_layout_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Overview layout history is immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_overview_layouts','pro_overview_layout_history','pro_overview_layout_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_overview_layout_history','pro_overview_layout_actions'] loop
  execute format('drop trigger if exists pro_overview_layout_immutable on public.%I',t);execute format('create trigger pro_overview_layout_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_overview_layout_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_overview_widgets','pro_overview_default_layout','pro_overview_person_ok','pro_overview_layout_read','pro_overview_layout_save','pro_work_sidebar_read','pro_role_route_capability','pro_overview_layout_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== work-timers-local.sql =====
-- LOCAL PRO ONLY. Round 8 (2026-11-15): person timer (clock-in) per job and activity.
-- One open timer per PERSON (the owner, or each company member working in the owner's company through
-- the role gate), across jobs and tabs: start → stop → review (minutes, date, activity, billable,
-- note can be edited) → save. Saving writes the time entry ONLY through the existing single time
-- writer (pro_time_mutate 'manual', which creates exactly one job-cost time line) and records who
-- worked in pro_time_entry_people. Discard keeps the row (status 'discarded'); nothing is deleted.
-- Not payroll; nothing is sent. Patterns: RLS on, service_role-only, CAS 40001, idempotent actionId,
-- immutable action receipts and history, America/Costa_Rica dates.
begin;
create table if not exists public.pro_work_timers(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 person_id uuid not null,person_name text not null default '' check(length(person_name)<=160),
 work_id text not null,activity_id uuid,billable boolean not null default true,note text not null default '' check(length(note)<=300),
 status text not null check(status in('running','stopped','saved','discarded')),
 started_at timestamptz not null,stopped_at timestamptz,time_entry_id uuid,
 revision integer not null default 1 check(revision>0),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,activity_id) references public.pro_time_activities(owner_id,id),
 check(status='running' and stopped_at is null and time_entry_id is null or status in('stopped','discarded') and stopped_at is not null and time_entry_id is null or status='saved' and stopped_at is not null and time_entry_id is not null));
-- One open (running or awaiting review) timer per person.
create unique index if not exists pro_work_timers_one_open on public.pro_work_timers(owner_id,person_id) where status in('running','stopped');
create table if not exists public.pro_work_timer_history(
 owner_id uuid not null,timer_id uuid not null,action_id uuid not null,action text not null check(action in('start','stop','discard','save')),
 actor_id uuid not null,before_row jsonb,after_row jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_work_timer_actions(
 owner_id uuid not null,person_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,action_id));

create or replace function public.pro_work_timer_json(t public.pro_work_timers) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',t.id,'workId',t.work_id,'service',(select w.service from public.pro_work w where w.user_id=t.owner_id and w.id=t.work_id),
  'activityId',t.activity_id,'activityName',(select a.name from public.pro_time_activities a where a.owner_id=t.owner_id and a.id=t.activity_id),
  'billable',t.billable,'note',t.note,'status',t.status,'startedAt',t.started_at,'stoppedAt',t.stopped_at,
  'minutes',greatest(1,least(1440,ceil(extract(epoch from (coalesce(t.stopped_at,clock_timestamp())-t.started_at))/60)::integer)),
  'personName',t.person_name,'revision',t.revision,'timeEntryId',t.time_entry_id)
$$;
create or replace function public.pro_work_timer_person_ok(p_owner uuid,p_person uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(public.pro_private_work_tools_enabled(p_owner),false) and p_person is not null and public.pro_role_of(p_person,p_owner) is not null
$$;
create or replace function public.pro_work_timer_read(p_actor uuid,p_person uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare t public.pro_work_timers;
begin
 if not public.pro_work_timer_person_ok(p_actor,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into t from public.pro_work_timers where owner_id=p_actor and person_id=p_person and status in('running','stopped');
 return jsonb_build_object('timer',case when found then public.pro_work_timer_json(t) end,'serverNow',clock_timestamp(),
  'activities',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'billable',a.billable) order by a.name,a.id) from public.pro_time_activities a where a.owner_id=p_actor and not a.archived),'[]'::jsonb));
end $$;

create or replace function public.pro_work_timer_mutate(p_actor uuid,p_person uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;tid uuid;keys text[];hash text:=md5(p_input::text);prior public.pro_work_timer_actions;
 t public.pro_work_timers;before_json jsonb;answer jsonb;rev integer;v_minutes integer;v_day date;today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;
 v_activity uuid;v_note text;entry uuid;written jsonb;who text;
begin
 if not public.pro_work_timer_person_ok(p_actor,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid timer' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act is null or not(
   act='start' and keys=array['action','actionId','activityId','billable','note','workId']
   or act in('stop','discard') and keys=array['action','actionId','revision','timerId']
   or act='save' and keys=array['action','actionId','activityId','billable','date','minutes','note','revision','timerId']) then raise exception 'Invalid timer' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;tid:=nullif(p_input->>'timerId','')::uuid;v_activity:=nullif(p_input->>'activityId','')::uuid;
  exception when others then raise exception 'Invalid timer' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-timer:'||p_actor::text||':'||p_person::text,0));
 select * into prior from public.pro_work_timer_actions where owner_id=p_actor and person_id=p_person and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if act in('start','save') then
  if jsonb_typeof(p_input->'billable') is distinct from 'boolean' or jsonb_typeof(p_input->'note') is distinct from 'string' or length(btrim(p_input->>'note'))>300
   or jsonb_typeof(p_input->'activityId') not in('string','null') then raise exception 'Invalid timer' using errcode='22023';end if;
  v_note:=btrim(p_input->>'note');
  if v_activity is not null and not exists(select 1 from public.pro_time_activities where owner_id=p_actor and id=v_activity and not archived) then raise exception 'Activity unavailable' using errcode='40001';end if;
 end if;
 if act='start' then
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_input->>'workId' and not coalesce(cancelled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
  if exists(select 1 from public.pro_work_timers where owner_id=p_actor and person_id=p_person and status in('running','stopped')) then raise exception 'A timer is already open' using errcode='40001';end if;
  who:=left(coalesce(nullif(btrim((select member_name from public.pro_company_members where owner_id=p_actor and member_user_id=p_person and active)),''),nullif(public.pro_team_name(p_person),''),'Propietario'),160);
  insert into public.pro_work_timers(owner_id,id,person_id,person_name,work_id,activity_id,billable,note,status,started_at)
   values(p_actor,aid,p_person,who,p_input->>'workId',v_activity,(p_input->>'billable')::boolean,v_note,'running',clock_timestamp()) returning * into t;
 else
  begin rev:=(p_input->>'revision')::integer;exception when others then raise exception 'Invalid timer' using errcode='22023';end;
  select * into t from public.pro_work_timers where owner_id=p_actor and id=tid and person_id=p_person for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if t.revision<>rev then raise exception 'Timer changed' using errcode='40001';end if;
  before_json:=public.pro_work_timer_json(t);
  if act='stop' then
   if t.status<>'running' then raise exception 'Timer not running' using errcode='40001';end if;
   update public.pro_work_timers set status='stopped',stopped_at=clock_timestamp(),revision=revision+1 where owner_id=p_actor and id=tid returning * into t;
  elsif act='discard' then
   if t.status not in('running','stopped') then raise exception 'Timer closed' using errcode='40001';end if;
   update public.pro_work_timers set status='discarded',stopped_at=coalesce(stopped_at,clock_timestamp()),revision=revision+1 where owner_id=p_actor and id=tid returning * into t;
  else
   if t.status<>'stopped' then raise exception 'Stop the timer before saving' using errcode='40001';end if;
   if jsonb_typeof(p_input->'minutes') is distinct from 'number' or not coalesce((p_input->>'minutes')~'^[0-9]{1,4}$',false) then raise exception 'Invalid minutes' using errcode='22023';end if;
   v_minutes:=(p_input->>'minutes')::integer;
   begin v_day:=(p_input->>'date')::date;exception when others then raise exception 'Invalid date' using errcode='22023';end;
   if v_minutes not between 1 and 1440 or v_day is null or v_day>today or v_day<today-366 then raise exception 'Invalid time values' using errcode='22023';end if;
   entry:=gen_random_uuid();
   -- The single time writer: one time entry and its one job-cost line.
   written:=public.pro_time_mutate(p_actor,jsonb_build_object('action','manual','actionId',gen_random_uuid(),'entryId',entry,'workId',t.work_id,
     'activityId',v_activity,'billable',(p_input->>'billable')::boolean,'date',v_day::text,'minutes',v_minutes,'note',v_note));
   insert into public.pro_time_entry_people(owner_id,entry_id,grant_id,name) values(p_actor,entry,null,coalesce(nullif(t.person_name,''),'Propietario')) on conflict(owner_id,entry_id) do nothing;
   update public.pro_work_timers set status='saved',time_entry_id=entry,activity_id=v_activity,billable=(p_input->>'billable')::boolean,note=v_note,revision=revision+1 where owner_id=p_actor and id=tid returning * into t;
  end if;
 end if;
 insert into public.pro_work_timer_history(owner_id,timer_id,action_id,action,actor_id,before_row,after_row) values(p_actor,t.id,aid,act,p_person,before_json,public.pro_work_timer_json(t));
 answer:=jsonb_build_object('action',act,'timer',public.pro_work_timer_json(t),'entryId',t.time_entry_id);
 insert into public.pro_work_timer_actions(owner_id,person_id,action_id,input_hash,result) values(p_actor,p_person,aid,hash,answer);
 return answer;
end $$;

create or replace function public.pro_work_timer_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Timer history is immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_work_timers','pro_work_timer_history','pro_work_timer_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_work_timer_history','pro_work_timer_actions'] loop
  execute format('drop trigger if exists pro_work_timer_immutable on public.%I',t);execute format('create trigger pro_work_timer_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_work_timer_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_work_timer_json','pro_work_timer_person_ok','pro_work_timer_read','pro_work_timer_mutate','pro_work_timer_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';
